    "cps_solution": "\n<strong>【資源調度方程與整數約束】</strong><br>\n<strong>步驟 1（設定工程模型）：</strong><br>\n工程總量設為 $1$。規定工期 $T = 3$ 天，則總需求工效為：$E_{\\text{req}} = \\frac{1}{3}$。<br>\n<strong>步驟 2（已知工效帶入）：</strong><br>\n- 甲隊每天完成：$E_A = \\frac{1}{6}$。<br>\n- 設需安排 $k$ 支乙隊子隊伍，每支每天完成：$E_B = \\frac{1}{12}$。<br>\n<strong>步驟 3（列方程求解）：</strong><br>\n$$E_A + k \\times E_B = \\frac{1}{6} + \\frac{k}{12} = \\frac{1}{3}$$\n兩邊同乘以 $12$：<br>\n$$2 + k = 4 \\implies k = 2$$<br>\n<strong>結論：</strong>至少需搭配 $2$ 支乙隊隊伍同時作業，才能保證在 $3$ 天內完工。\n",
