    "text_scrutiny": "澳門某大型綜合商場週年慶推出兩款結帳優惠方案（限滿 500 元使用）：\n方案 A：『全單先享八折（× $\\frac{4}{5}$），折後金額再立減 100 元』；\n方案 B：『全單先立減 100 元，剩餘金額再享八折（× $\\frac{4}{5}$）』。\n小明媽媽選購了一件標價 800 元的大衣，銷售員推薦方案 A，宣稱『先打大折扣最划算』。請你進行數學審計。",
