    "cps_challenge": "【決策樹分支設計】編寫一段偽代碼，輸入購物金額 x 與折扣參數，自動輸出最優付款方案與節省金額差值。",
    "cps_solution": "\n<strong>【決策樹分支演算法與最優策略】</strong><br>\n<strong>步驟 1（雙重促銷代數模型）：</strong><br>\n設商品原價為 $P$，滿減金額為 $M$，折扣率為 $d$（$0 < d < 1$）。<br>\n- 方案一（先折後減）：$P_1 = P \\times d - M$<br>\n- 方案二（先減後折）：$P_2 = (P - M) \\times d = P \\times d - M \\times d$<br>\n<strong>步驟 2（差值分析）：</strong><br>\n$$P_2 - P_1 = (P \\times d - M \\times d) - (P \\times d - M) = M \\times (1 - d) > 0$$\n因 $d < 1$，故 $1 - d > 0$，$P_1$ 恆小於 $P_2$。<br>\n<strong>步驟 3（演算法偽代碼）：</strong><br>\n```text\nFUNCTION BestDiscount(P, M, d):\n    IF P < M THEN RETURN (P * d, \"僅可享受打折\")\n    P1 = P * d - M\n    P2 = (P - M) * d\n    diff = M * (1 - d)\n    RETURN (P1, \"方案一(先折後減)更省\", diff)\n```<br>\n<strong>商家後台審計結論：</strong>商家後台預設『先減後折』，是因為先扣掉券面額後，打折基數縮小，顧客實際獲得的讓利少 $M \\times (1 - d)$ 元，商家利潤更高。\n",
    "exp_name": "促銷折算演算法順序沙盒實驗台",
    "exp_principle": "方案一：$P \\times 0.8 - 50$；方案二：$(P - 50) \\times 0.8$ = $P \\times 0.8 - 40$。兩者差額為 50 - 40 = 10 元，即減價金額乘以折扣差（$50 \\times (1 - 0.8)$）。",
