    "cps_solution": "\n<strong>【階梯非線性計費演算法】</strong><br>\n<strong>步驟 1（澳門/常見階梯電費分檔規則）：</strong><br>\n- 第一檔：$0 \\le E \\le 200\\text{ 度}$，單價 $P_1 = 1.0\\text{ 元/度}$<br>\n- 第二檔：$201 \\le E \\le 400\\text{ 度}$，單價 $P_2 = 1.5\\text{ 元/度}$<br>\n- 第三檔：$E > 400\\text{ 度}$，單價 $P_3 = 2.0\\text{ 元/度}$<br>\n<strong>步驟 2（分段條件函數推導）：</strong><br>\n- 若 $E \\le 200$：$\\text{Cost} = E \\times 1.0$<br>\n- 若 $200 < E \\le 400$：$\\text{Cost} = 200 \\times 1.0 + (E - 200) \\times 1.5$<br>\n- 若 $E > 400$：$\\text{Cost} = 200 \\times 1.0 + 200 \\times 1.5 + (E - 400) \\times 2.0 = 500 + (E - 400) \\times 2.0$<br>\n<strong>步驟 3（碳排放計算）：</strong><br>\n$$\\text{CO}_2\\text{ 排放 (kg)} = E \\times 0.537\\text{ kg/度}$$\n",
    "exp_name": "家庭階梯電費與碳排放計算動態曲線實驗台",
