      "evidence": "設一瓶 500mL 飲品原含維生素 2mg。按甲款『提高 $50\\%$』後含量為 3mg，佔總容量的 $0.0006\\%$；若按乙款『含量 $50\\%$』則需含維生素 250,000mg，兩者相差超過 83,000 倍！",
      "reasoning": "百分數的核心在於基準量（單位『1』）。甲款的基準量是『原本微量的維生素（2mg）』，$50\\%$ 代表相對增量；乙款的基準量是『整瓶飲料的全部體積（500mL）』，$50\\%$ 代表絕對成分佔比。偷換基準量是商業廣告欺騙公眾的典型修辭手法。",
      "rebuttal": "反駁主播『都是50%所以一樣』的說法：忽略基準量談百分比就像『增加 $50\\%$ 的零用錢（從10元變15元）』與『拿走全家財產的 $50\\%$』一樣荒謬。"
