    "cps_solution": "\n<strong>【媒體與商業廣告三大陷阱識別】</strong><br>\n<strong>陷阱 1（偷換基準量 / 縮減份量）：</strong><br>\n宣稱『每份僅含糖 $4.5\\text{ g}$』，但一瓶飲料淨重 $500\\text{ g}$ 標註為 $10$ 份（每份僅 $50\\text{ g}$）。整瓶實際含糖量高達 $4.5 \\times 10 = 45\\text{ g}$，相當於 $10$ 塊方糖，超出兒童每日糖攝入上限。<br>\n<strong>陷阱 2（百分率基數不對等）：</strong><br>\n宣稱『脂肪含量降低 $50\\%$』，若原配方每 $100\\text{ g}$ 含脂肪 $0.2\\text{ g}$，降至 $0.1\\text{ g}$ 雖然降了 $50\\%$，但絕對值僅減少 $0.1\\text{ g}$，在營養學上對健康影響微乎其微。<br>\n<strong>陷阱 3（模糊字眼『低於常規』）：</strong><br>\n未明確指明常規標準之具體數值與品牌，缺乏科學參照對照組。\n",
    "exp_name": "商業宣傳商品標籤文字陷阱審查放大鏡",
    "exp_principle": "百分數的本質取決於基準量（單位『1』）。『相對增長率（比原本多50%）』與『絕對成分佔比（在總量中佔50%）』存在本質區別，不可偷換概念。",
