      "reasoning": "正視圖決定了每一列投影中積木高度的上確界（Supremum）。為求最少，除必備最高峰外，其餘底座位置全部取幾何存在性的最低限度 1；為求最多，所有底座格子均取該列允許的峰值上限。",
