    "cps_solution": "\n<strong>【空間約束下積木數量極值演算法】</strong><br>\n<strong>步驟 1（最少方塊數量計算）：</strong><br>\n依據正視圖 $[2, 3, 1]$ 與俯視圖 $3 \\times 3$：<br>\n每列的最高高度必須滿足約束，且每列至少安排一個方塊達到該列最高值，其餘為 $1$。<br>\n最少需要滿足各列最大值需求：$\\sum \\max(col_i) + \\text{其餘支撐} = 2 + 3 + 1 + 2 = 8\\text{ 塊}$。<br>\n<strong>步驟 2（最多方塊數量計算）：</strong><br>\n在俯視圖的所有有效網格上，每一格都放滿該列的最大允許高度：<br>\n$$\\text{Max} = (2 \\times 3) + (3 \\times 3) + (1 \\times 3) = 6 + 9 + 3 = 18\\text{ 塊}$$\n",
    "exp_name": "第 11 週專題動態實驗台：無人機航拍與澳門世遺牌坊重建",
