    "cps_challenge": "【吸水材料體積測量演算法】若要測量一塊海綿的實體體積（排除內部孔隙），請設計一套包含『飽和吸水預處理』的標準實驗步驟演算法。",
    "cps_solution": "\n<strong>【飽和吸水預處理與排除系統誤差演算法】</strong><br>\n<strong>步驟 1（系統誤差分析）：</strong><br>\n若直接將乾燥多孔海綿投入水中，海綿內部孔隙會吸收水分，導致水面上升高度 $\\Delta h$ 嚴重偏小，測得體積遠小於真實體積。<br>\n<strong>步驟 2（標準科學實驗步驟演算法）：</strong><br>\n1. **飽和吸水**：將海綿完全浸沒在清水中充分吸飽水，直至內部無氣泡冒出；<br>\n2. **輕甩表面**：取出海綿，輕輕甩去附著在表面非孔隙的浮水；<br>\n3. **排水測量**：將飽和吸水後的海綿浸入盛有已知體積 $V_0$ 的量筒中；<br>\n4. **讀數計算**：記錄新水面讀數 $V_1$，海綿骨架固體真實體積為：$V = V_1 - V_0$。\n",
    "exp_name": "第 13 週專題動態實驗台：阿基米德王冠之謎與沉降測量",
