    "cps_solution": "\n<strong>【多維度計量單位轉化階梯模型】</strong><br>\n<strong>換算進制幾何推導：</strong><br>\n- **長度（一維）**：$1\\text{ m} = 10\\text{ dm} = 100\\text{ cm}$（進制為 $10^1$）<br>\n- **面積（二維）**：$1\\text{ m}^2 = 10^2\\text{ dm}^2 = 100\\text{ dm}^2$（進制為 $10^2 = 100$）<br>\n- **體積（三維）**：$1\\text{ m}^3 = 10^3\\text{ dm}^3 = 1,000\\text{ dm}^3 = 1,000,000\\text{ cm}^3$（進制為 $10^3 = 1,000$）<br>\n- **容積等價**：$1\\text{ dm}^3 = 1\\text{ L}$；$1\\text{ cm}^3 = 1\\text{ mL}$<br>\n故：$1\\text{ m}^3 = 1,000\\text{ L} = 1,000,000\\text{ mL}$。水塘蓄水量 $500,000\\text{ m}^3$ 即為 $5\\text{ 億公升}$。\n",
