    "cps_solution": "\n<strong>【統計圖表審查五項黃金標準（Checklist）】</strong><br>\n<strong>審查項 1（坐標軸基點）：</strong>縱軸（Y軸）數值起點是否為 $0$？若截斷是否有明顯波浪折斷線標記？<br>\n<strong>審查項 2（刻度均勻性）：</strong>軸線上的區間刻度是否等距均勻，是否存在對數壓縮卻未註明？<br>\n<strong>審查項 3（視覺面積比例）：</strong>柱狀圖面積增長是否與真實數值增長成正比（防範長寬雙倍放大導致面積 $4$ 倍誇大）？<br>\n<strong>審查項 4（時間週期完整性）：</strong>橫軸時間是否刻意選取局部峰值/谷值進行偏誤對比？<br>\n<strong>審查項 5（數據來源信度）：</strong>圖表下方是否清楚註記樣本規模 $N$ 與權威統計機構出處。\n",
