    "text_scrutiny": "智能手錶電池供應商遴選大會。兩家電池廠商提供質檢報告：\n• 廠商 A：隨機抽檢 10 塊電池，全部合格，合格率高達【$100\\%$】！宣傳語：《零缺陷完美電池》\n• 廠商 B：隨機抽檢 10,000 塊電池，合格 9,920 塊，合格率為【$99.2\\%$】。\n採購經理提議：『$100\\%$ 絕對優於 $99.2\\%$，我們必須把億元訂單全給廠商 A！』請你作為質量審計專家進行論證審核。",
