      "evidence": "廠商 A 的樣本量僅為 n=10，若其真實次品率為 $2\\%$，抽檢 10 塊全合格的機率高達 0.98^10 ≈ $81.7\\%$，完全屬於小樣本運氣；而廠商 B 在 n=10,000 的超大樣本下依然維持 $99.2\\%$ 合格率，代表其在大規模工業化量產中具備極其穩定的工程控制能力。",
