    "cps_challenge": "【「$72$ 法則」驗證演算法】編寫一個迴圈，輸入年利率 r，模擬計算本金連續累乘 (1+r) 直至大於等於 2 的實際年數，並與 72/r 進行誤差對比。",
    "cps_solution": "\n<strong>【72 法則與複利指數翻倍推導】</strong><br>\n<strong>步驟 1（翻倍時間方程式）：</strong><br>\n本金翻倍即 $(1 + r)^t = 2$。<br>\n兩邊取自然對數：$t \\cdot \\ln(1 + r) = \\ln 2 \\approx 0.693$。<br>\n當 $r$ 較小時，$\\ln(1 + r) \\approx r$，故：<br>\n$$t \\approx \\frac{0.693}{r} \\approx \\frac{72}{100r}$$\n<strong>步驟 2（實例比對）：</strong><br>\n當年利率 $r = 6\\%$ 時：<br>\n- 72法則預估：$t \\approx \\frac{72}{6} = 12\\text{ 年}$。<br>\n- 精確計算：$(1.06)^{11.9} \\approx 2.00$，誤差僅約 $0.1$ 年。\n",
