      "evidence": "相鄰跑道差公式：ΔL = 2π(r + d) - $2\\pi r$ = 2πd。已知道寬 d = 1.22m，相鄰每道差 ΔL = 2 × 3.1416 × 1.22 ≈ 7.665 米。從第 1 道到第 8 道共跨越 7 個道寬間距，總差額為 7 × 7.665 = 53.655 米。",
      "reasoning": "外道彎道半徑大於內道，每圈彎道周長隨半徑成 2π 的線性倍數增加。直道部分長度完全相等，在計算差值時相減抵消（2L - 2L = 0）。因此，總路程差僅由圓周長公式中的半徑增量決定。若外道不前移，外道選手將多跑 53.66 米冤枉路。",
      "rebuttal": "反駁『視覺前移就是佔便宜』的直覺：人的眼睛容易只看到起跑線的相對位置，而忽視了沿著弧線跑步時外圈的大曲率半徑。起跑前移精準補償了幾何半徑擴大帶來的額外弧長。"
