    "unit": "6下 課次23: 圓的面積 (二)",
    "title": "披薩店的幾何密碼——面積二次方律與消費者性價比決策",
    "domain": "數量 (Quantity)",
    "pisa_coords": "【思維範疇】數量 (Quantity) | 【情境】日常生活與消費經濟 | 【認知過程】幾何模型應用與非線性增長決策 | 【前瞻要素】面積平方律、消費者防禦",
    "text_scrutiny": "澳門某連鎖披薩店真實點餐情境：\n顧客點了一份 12 吋（直徑 12 英寸）的至尊披薩（售價 120 元）。服務生面帶微笑前來道歉：『抱歉先生，12 吋餅底用完了，我們免費為您升級替換為【兩個 8 吋】披薩，8 吋直徑是 8，8+8 = 16 吋，您賺了足足 4 吋！』顧客心滿意足準備答應。請你作為隨行朋友進行數學審查。",
    "misconception": "學生普遍陷入線性一維思維陷阱，認為『8 + 8 = 16 吋 > 12 吋，所以兩個 8 吋肯定更多』，混淆了直徑（一維長度）與面積（二維平方）的本質區別。",
    "cer": {
      "claim": "服務生的替換方案讓顧客蒙受了損失，兩個 8 吋披薩的總量明顯小於一個 12 吋披薩，顧客虧損了約 $11.1\\%$ 的披薩餅體。",
      "evidence": "一個 12 吋披薩面積為 π × ($\\frac{12}{2}$)² = 36π ≈ 113.1 平方英吋；兩個 8 吋披薩總面積為 2 × [π × ($\\frac{8}{2}$)²] = 2 × 16π = 32π ≈ 100.5 平方英吋。36π > 32π，顧客淨少吃 4π（約 12.57 平方英吋）。",
      "reasoning": "圓面積與直徑（或半徑）的平方成正比（S ∝ d²），而非與直徑成正比。一維長度的簡單相加（8+8=16）完全忽視了二維空間擴展的平方幾何規律。披薩吃的是面積而非直徑長度。",
      "rebuttal": "反駁服務生『8+8=16 賺了』的荒謬推銷：把兩個小披薩排成一排確實長度是 16 吋，但那是線性跨度。如果按此邏輯，12 個 1 吋披薩（總長12吋）面積只有 12×0.25π = 3π，縮水了整整 12 倍！"
    },
    "cps_challenge": "【披薩性價比演算法】編寫一個函數 pizza_value(diameter_inches, price)，計算每平方英吋披薩的單價（元/inch²），找出店內性價比最高的尺寸。",
    "cps_solution": "\n<strong>【披薩面積二次方縮放與性價比演算法】</strong><br>\n<strong>步驟 1（面積二次方律）：</strong><br>\n披薩面積與直徑的平方成正比：$S = \\pi (\\frac{D}{2})^2 = \\frac{\\pi D^2}{4}$。<br>\n- 12 吋大披薩面積：$S_{12} = \\pi \\times 6^2 = 36\\pi \\approx 113.1\\text{ 平方英吋}$。<br>\n- 9 吋披薩面積：$S_9 = \\pi \\times 4.5^2 = 20.25\\pi \\approx 63.6\\text{ 平方英吋}$。<br>\n- 2 個 9 吋披薩總面積：$2 \\times 20.25\\pi = 40.5\\pi \\approx 127.2\\text{ 平方英吋}$。<br>\n<strong>步驟 2（單位面積價格演算法）：</strong><br>\n$$\\text{UnitPrice} = \\frac{\\text{售價 } P}{S}$$\n比較單價後即可精確得出最省錢的尺寸組合方案。\n",
    "exp_name": "第 23 週專題動態實驗台：披薩店的幾何密碼",
    "exp_principle": "圓面積與直徑（或半徑）的平方成正比（S ∝ d²），而非與直徑成正比。一維長度的簡單相加（8+8=16）完全忽視了二維空間擴展的平方幾何規律。披薩吃的是面積而非直徑長度。",
