    "pisa_coords": "【思維範疇】變化與關係 (Change & Relationships) | 【情境】交通法規與行車安全 | 【認知過程】非線性調和平均數建模與物理分析 | 【前瞻要素】區間測速、反直覺論證",
    "text_scrutiny": "澳門治安警察局交通廳在友誼大橋（全長約 $4.4\\text{ 公里}$，限速 $80\\text{ km/h}$）啟用區間測速系統。\n某司機駕駛私家車過橋：前半程（2.2公里）因避讓慢車，行駛速率為 60 km/h；後半程（2.2公里）路況通暢，司機將車速提高到 100 km/h。交警大隊以『全程平均超速』為由開出超速罰單。司機不服行政覆議：『前半程 60，後半程 100，我的平均速率剛好是 (60 + 100) ÷ 2 = $80\\text{ km/h}$，正好壓在限速上限，憑什麼罰我？』",
