      "evidence": "全程總路程 S = 4.4 km。前半程耗時 t1 = 2.$\\frac{2}{60}$ 小時（約132秒）；後半程耗時 t2 = 2.$\\frac{2}{100}$ 小時（約79.2秒）。總耗時 T = 211.2 秒 = 0.05867 小時。全程平均速率 v = 4.4 ÷ 0.05867 = 75 km/h < $80\\text{ km/h}$。調和平均公式：2v1v2/(v1+v2) = 2×60×$\\frac{100}{160}$ = 75 km/h。",
      "reasoning": "速度的定義是 v = S/T。平均速度的分母是總時間。在路程相等的兩段行駛中，低速（60km/h）所耗費的時間（132秒）遠大於高速（100km/h）耗費的時間（79.2秒）。低速時間在權重中佔據主導地位，將整體平均速率強烈拉向低速一側。",
      "rebuttal": "反駁 (v1+v2)/2 的直覺：只有當兩段行駛『時間相等』時（例如開 60 開了 1 小時，開 100 開了 1 小時），平均速度才是 80。路程相等時絕不可套用算術平均。"
