    "cps_challenge": "【極限時間悖論】用數學方程證明：若某車前半程以 $40\\text{ km/h}$ 行駛，為什麼後半程無論開多快（哪怕達到光速），全程平均速率也永遠無法達到 $80\\text{ km/h}$？",
    "cps_solution": "\n<strong>【調和平均與極限時間悖論證明】</strong><br>\n<strong>步驟 1（行程時間方程）：</strong><br>\n設全程距離為 $2S$。前半程距離為 $S$，速度 $v_1 = 40\\text{ km/h}$，耗時：$t_1 = \\frac{S}{40}$。<br>\n後半程距離為 $S$，速度為 $v_2$，耗時：$t_2 = \\frac{S}{v_2}$。<br>\n全程平均速度公式為：<br>\n$$\\bar{v} = \\frac{2S}{t_1 + t_2} = \\frac{2S}{\\frac{S}{40} + \\frac{S}{v_2}} = \\frac{2}{\\frac{1}{40} + \\frac{1}{v_2}}$$\n<strong>步驟 2（極限求解）：</strong><br>\n若全程平均速度要達到 $80\\text{ km/h}$：<br>\n$$\\frac{2}{\\frac{1}{40} + \\frac{1}{v_2}} = 80 \\implies \\frac{1}{40} + \\frac{1}{v_2} = \\frac{2}{80} = \\frac{1}{40} \\implies \\frac{1}{v_2} = 0 \\implies v_2 \\to \\infty$$<br>\n因為光速有限（$v_2 < c$），後半程無論開多快，耗時 $t_2 > 0$，總時間必然大於 $\\frac{S}{40}$，因此全程平均時速<strong>絕對不可能達到 $80\\text{ km/h}$</strong>！\n",
