    "text_scrutiny": "港珠澳大橋（全長約 55 公里）穿梭金巴調度中心大屏幕動態追蹤：\n相遇情境：上午 $9 : 00$，甲巴從澳門口岸以 $80\\text{ km/h}$ 駛向香港，同時乙巴從香港口岸以 70 km/h 駛向澳門；\n追及情境：上午 $9 : 30$，一輛時速 60 km/h 的工程巡邏車已開出 15 公里，一輛時速 90 km/h 的特勤警車從同一起點出發緊急追趕。\n調度中心需要精確預測：兩車何時在海面橋上交錯相遇？警車行駛多少公里後能追上巡邏車？",
