    "cps_solution": "\n<strong>【動態時空建模與防撞警報演算法】</strong><br>\n<strong>步驟 1（相遇模型方程）：</strong><br>\n兩車相向行駛，初始間距為 $D$，車速分別為 $v_1, v_2$。<br>\n相對接近速度為：$v_{\\text{rel}} = v_1 + v_2$。<br>\n相遇剩餘時間公式：$t_{\\text{remain}} = \\frac{D}{v_1 + v_2}$。<br>\n<strong>步驟 2（防撞警報偽代碼）：</strong><br>\n```python\ndef collision_warning(dist_meters, v1_kmh, v2_kmh):\n    v_rel_ms = (v1_kmh + v2_kmh) / 3.6\n    time_to_impact = dist_meters / v_rel_ms\n    if time_to_impact <= 5.0:\n        return {\"status\": \"EMERGENCY_BRAKE\", \"time_s\": round(time_to_impact, 2)}\n    return {\"status\": \"SAFE\", \"time_s\": round(time_to_impact, 2)}\n```\n",
