    "pisa_coords": "【思維範疇】變化與關係 (Change & Relationships) | 【情境】日常生活與智能穿戴監測 | 【認知過程】圖表與物理現實相互轉化 | 【前瞻要素】多模態圖表解碼、斜率直覺",
    "text_scrutiny": "澳門智慧手環記錄小強週六從聖五校區步行至大三巴牌坊再返回的『距離-時間（s-t）折線圖』審查：\n• 0-15 分鐘：線條平穩上升至 1200 米；\n• 15-35 分鐘：線條呈現一條水平直線（保持在 1200 米）；\n• 35-40 分鐘：線條劇烈陡峭上升至 1800 米；\n• 40-50 分鐘：線條呈現向下折返直達 0 米。\n體育老師提問：『水平線代表小強在飛速跑步嗎？線條下降代表小強在倒退著走嗎？哪一段運動速度最快？』",
    "misconception": "學生看圖表時容易把『折線形狀』直接等同於『地理地形或行走路線』，誤以為水平線是在平地走、上升是在爬坡、向下折返是從山頂走下來；或者不知道折線傾斜程度（斜率）代表速度大小。",
    "cer": {
      "claim": "折線圖反映的是時間與位移的函數關係而非地理地形；小強在 15-35 分鐘內完全處於靜止狀態，而在 40-50 分鐘折返時速度最快（180 m/min）。",
      "evidence": "15-35 分鐘內距離維持在 1200m，位移變化量 Δs = 0，速度 v = $\\frac{0}{20}$ = 0 m/min（靜止）。各段速度計算：0-15分 v1 = 80 m/min；35-40分 v2 = 120 m/min；40-50分 v3 = 1800m ÷ 10min = 180 m/min。180 > 120 > 80 > 0。",
      "reasoning": "在距離-時間圖中，折線的傾斜程度（斜率 Δs/Δt）嚴格代表物理運動速度。線條越陡峭，單位時間內位移變化越大，速度越快。向下傾斜僅代表運動方向反向（朝向參考原點），其絕對斜率依然反映運動快慢。",
      "rebuttal": "反駁『水平線是平地、向下是下坡』的直觀謬誤：手環記錄的是時間演進中的位置距離，不是海拔高度計。如果水平線是平地，時間不可能在靜止中前進，混淆坐標軸維度是圖表閱讀的致命傷。"
    },
    "cps_challenge": "【行程圖代碼繪製】給定一組路徑關鍵點坐標 [(0,0), (10, 800), (20, 800), (30, 0)]，寫出一段 Python Matplotlib 繪圖指令生成 s-t 圖並標註各段速率。",
    "cps_solution": "\n<strong>【運動圖表物理意義與斜率解讀】</strong><br>\n<strong>核心解讀原則：</strong><br>\n1. **位移-時間圖 ($s$-$t$)**：<br>\n   - 曲線斜率表示<strong>瞬時速度</strong>：$v = \\frac{\\Delta s}{\\Delta t}$。<br>\n   - 水平線段（$\\Delta s = 0$）表示<strong>原地靜止</strong>；<br>\n   - 負斜率表示<strong>反向折返運動</strong>。<br>\n2. **速度-時間圖 ($v$-$t$)**：<br>\n   - 曲線斜率表示<strong>加速度</strong>：$a = \\frac{\\Delta v}{\\Delta t}$；<br>\n   - 曲線與時間軸所圍成的『面積』代表<strong>總路程（位移）</strong>。\n",
    "exp_name": "第 26 週專題動態實驗台：解讀運動圖表",
    "exp_principle": "在距離-時間圖中，折線的傾斜程度（斜率 Δs/Δt）嚴格代表物理運動速度。線條越陡峭，單位時間內位移變化越大，速度越快。向下傾斜僅代表運動方向反向（朝向參考原點），其絕對斜率依然反映運動快慢。",
    "exp_steps": [
      "1. 打開線上實驗台，調節核心自變數滑桿與參數控制器。",
      "2. 觀察即時動態模擬畫布（平移/旋轉/添加元素），觀測數據變化趨勢。",
      "3. 點擊『數據記錄』，將測得數值填入下方觀測表格中，對比理論值與實驗值。"
    ],
