    "unit": "6下 課次27: 簡易方程 (一)",
    "title": "天平平衡原理與代數等量思維——從『逆向算術反推』到『順向代數建模』",
    "domain": "變化與關係 (Change & Relationships)",
    "pisa_coords": "【思維範疇】變化與關係 (Change & Relationships) | 【情境】科學實驗與代數結構 | 【認知過程】形式化符號表徵與等式基本性質 | 【前瞻要素】代數思維、結構對稱",
    "text_scrutiny": "物理天平砝碼實驗情境：\n天平左盤放著 3 個重量相同且標有『x』的神秘金屬球和 1 個 50 克的標準砝碼；右盤放著 1 個 200 克的標準砝碼，天平指針嚴格居中指向 0 刻度（完全平衡）。\n小明用算術法思考：『我先拿 200 減去 50 得 150，再除以 3 得 50！』\n老師引導：『如果問題變得無比複雜，包含多個未知量時，算術逆推往往讓人抓狂。如何用一個等式把天平兩邊的平衡關係記錄下來？』",
    "misconception": "小學生習慣了『看到加法用減法、看到乘法用除法』的逆向算術算式，面對方程『3x + 50 = 200』感到彆扭，總想一步寫出 x = (200-50)/3，抗拒『把未知數當作已知數參與運算』的代數思維躍遷。",
    "cer": {
      "claim": "代數方程 3x + 50 = 200 是描述平衡狀態的最優模型，方程解法本質是基於等式性質的等價變形，而非死記硬背的符號搬家。",
      "evidence": "依據等式基本性質一：等式兩邊同時減去 50，得 3x + 50 - 50 = 200 - 50，即 3x = 150；依據等式基本性質二：兩邊同時除以 3，得 3x ÷ 3 = 150 ÷ 3，即 x = 50 克。檢驗：左邊 = 3(50)+50 = 200 = 右邊，等式成立。",
      "reasoning": "算術思維要求思維必須具備極高的高空逆向反推能力；而代數思維允許我們『順著生活事實走』，直接用符號 x 代表未知量，把複雜的語義關係如實記錄為靜態等式。隨後透過形式化規則機器化解題，大幅降低了複雜問題的認知處理帶寬。",
      "rebuttal": "反駁『小學算術算得更快所以沒必要學方程』的短視：簡單問題算術確實快，但面對初高中物理運動學、化學方程式、經濟模型等多變量交織時，算術逆推會徹底崩潰，代數方程是通往現代高等科學的唯一橋樑。"
    },
    "cps_challenge": "【天平方程解題器】編寫一個解 $ax + b = c$ 的簡化演算法步驟：1. 檢查 a≠0；2. 計算 temp = c - b；3. 計算 x = temp / a；4. 返回 x 並自動驗算。",
    "cps_solution": "\n<strong>【天平公理與代數等量思維】</strong><br>\n<strong>步驟 1（代數等量公理）：</strong><br>\n- 天平兩端同時加上或減去相同質量，天平保持平衡：若 $A = B$，則 $A \\pm C = B \\pm C$；<br>\n- 天平兩端同時擴大或縮小相同倍數（不為0），天平保持平衡：若 $A = B$，則 $A \\times C = B \\times C$ 且 $\\frac{A}{C} = \\frac{B}{C}$ ($C \\ne 0$)。<br>\n<strong>步驟 2（解方程通用演算法步驟）：</strong><br>\n對於方程 $ax + b = c$ ($a \\ne 0$)：<br>\n1. 兩邊同減 $b$：$ax = c - b$<br>\n2. 兩邊同除以 $a$：$x = \\frac{c - b}{a}$<br>\n3. 代入原方程檢驗左邊是否等於右邊。\n",
    "exp_name": "第 27 週專題動態實驗台：天平平衡原理與代數等量思維",
    "exp_principle": "算術思維要求思維必須具備極高的高空逆向反推能力；而代數思維允許我們『順著生活事實走』，直接用符號 x 代表未知量，把複雜的語義關係如實記錄為靜態等式。隨後透過形式化規則機器化解題，大幅降低了複雜問題的認知處理帶寬。",
