    "cps_challenge": "【魔術生成器演算法】設計一個參數化魔術生成器：輸入希望最終顯現的魔術數字 K，自動逆推步驟2中應該讓觀眾加上哪個偶數值（公式：加數 = 2K + 4）。",
    "cps_solution": "\n<strong>【讀心術魔術背後的九餘數代數恆等式】</strong><br>\n<strong>步驟 1（代數符號展開）：</strong><br>\n設任意兩位數的十位數字為 $a$，個位數字為 $b$（其中 $1 \\le a \\le 9$，$0 \\le b \\le 9$）。<br>\n則該兩位數的數值可表示為：$10a + b$。<br>\n<strong>步驟 2（魔術操作運算）：</strong><br>\n讓觀眾減去其各位數字之和 $(a + b)$：<br>\n$$(10a + b) - (a + b) = 10a + b - a - b = 9a$$<br>\n<strong>步驟 3（代數揭秘）：</strong><br>\n無論個位數字 $b$ 是多少，運算結果恆等於 $9a$（永遠是 $9$ 的倍數：$9, 18, 27, 36, 45, 54, 63, 72, 81$）。魔術圖形表中只要在所有 $9$ 的倍數位置全部放置<strong>完全相同的符號</strong>，即可 $100\\%$ 命中觀眾心中的想法！\n",
