// App State
let currentWeek = 1;
let currentFilter = 'all';
let recordedTables = {};
let animationFrameId = null;

// DOM Elements
const sidebar = document.getElementById('sidebar');
const sidebarToggle = document.getElementById('sidebarToggle');
const lessonList = document.getElementById('lessonList');
const weekSelect = document.getElementById('weekSelect');
const btnPrevWeek = document.getElementById('btnPrevWeek');
const btnNextWeek = document.getElementById('btnNextWeek');
const btnToggleCER = document.getElementById('btnToggleCER');
const btnFullscreen = document.getElementById('btnFullscreen');
const cerCard = document.getElementById('cerCard');
const cerHeader = document.getElementById('cerHeader');
const lessonSearch = document.getElementById('lessonSearch');
const filterTabs = document.querySelectorAll('.filter-tab');
const toastEl = document.getElementById('toast');

// Solution Elements
const btnToggleSolution = document.getElementById('btnToggleSolution');
const solutionBox = document.getElementById('solutionBox');
const solutionContent = document.getElementById('solutionContent');
const solutionBtnText = document.getElementById('solutionBtnText');

// OMML Elements
const ommlTitleEl = document.getElementById('ommlTitle');
const mathjaxFormulaEl = document.getElementById('mathjaxFormula');
const ommlXmlBox = document.getElementById('ommlXmlBox');
const ommlXmlText = document.getElementById('ommlXmlText');
const btnCopyOmml = document.getElementById('btnCopyOmml');
const btnToggleOmmlXml = document.getElementById('btnToggleOmmlXml');

// Initialize App
document.addEventListener('DOMContentLoaded', () => {
  populateSidebar();
  populateDropdown();
  setupEventListeners();
  loadWeek(1);
});

function showToast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  setTimeout(() => toastEl.classList.remove('show'), 2400);
}

function populateSidebar() {
  lessonList.innerHTML = '';
  const searchVal = lessonSearch.value.trim().toLowerCase();

  LESSONS_DATA.forEach(l => {
    if (currentFilter === 't1' && l.week > 15) return;
    if (currentFilter === 't2' && l.week <= 15) return;
    if (searchVal && !l.title.toLowerCase().includes(searchVal) && !String(l.week).includes(searchVal)) return;

    const item = document.createElement('div');
    item.className = `lesson-item ${l.week === currentWeek ? 'active' : ''}`;
    item.onclick = () => loadWeek(l.week);

    item.innerHTML = `
      <div class="item-header">
        <span class="item-week">第 ${String(l.week).padStart(2, '0')} 週</span>
        <span class="item-domain">${l.domain.split(' ')[0]}</span>
      </div>
      <div class="item-title">${l.title}</div>
    `;
    lessonList.appendChild(item);
  });
}

function populateDropdown() {
  weekSelect.innerHTML = '';
  LESSONS_DATA.forEach(l => {
    const opt = document.createElement('option');
    opt.value = l.week;
    opt.textContent = `第 ${String(l.week).padStart(2, '0')} 週: ${l.title.substring(0, 22)}...`;
    weekSelect.appendChild(opt);
  });
  weekSelect.value = currentWeek;
}

function setupEventListeners() {
  sidebarToggle.onclick = () => sidebar.classList.toggle('collapsed');
  btnPrevWeek.onclick = () => { if (currentWeek > 1) loadWeek(currentWeek - 1); };
  btnNextWeek.onclick = () => { if (currentWeek < 30) loadWeek(currentWeek + 1); };
  weekSelect.onchange = (e) => loadWeek(parseInt(e.target.value));

  btnToggleCER.onclick = () => cerCard.classList.toggle('collapsed');
  cerHeader.onclick = () => cerCard.classList.toggle('collapsed');

  // Solution Toggle
  if (btnToggleSolution) {
    btnToggleSolution.onclick = () => {
      const isHidden = solutionBox.style.display === 'none';
      if (isHidden) {
        solutionBox.style.display = 'block';
        solutionBtnText.textContent = '收起參考解答';
        btnToggleSolution.classList.add('active');
        if (window.MathJax && window.MathJax.typesetPromise) {
          MathJax.typesetPromise([solutionBox]).catch(() => {});
        }
      } else {
        solutionBox.style.display = 'none';
        solutionBtnText.textContent = '查看參考解答與思維解析';
        btnToggleSolution.classList.remove('active');
      }
    };
  }

  filterTabs.forEach(tab => {
    tab.onclick = () => {
      filterTabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentFilter = tab.dataset.filter;
      populateSidebar();
    };
  });

  lessonSearch.oninput = () => populateSidebar();

  btnFullscreen.onclick = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  };

  if (btnToggleOmmlXml) {
    btnToggleOmmlXml.onclick = () => {
      if (ommlXmlBox.style.display === 'none') {
        ommlXmlBox.style.display = 'flex';
        btnToggleOmmlXml.textContent = '隱藏代碼';
      } else {
        ommlXmlBox.style.display = 'none';
        btnToggleOmmlXml.textContent = '檢視代碼';
      }
    };
  }

  btnCopyOmml.onclick = () => {
    const lesson = LESSONS_DATA[currentWeek - 1];
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(lesson.omml_xml).then(() => {
        btnCopyOmml.innerHTML = '<i class="fa-solid fa-check"></i> 已複製公式！';
        btnCopyOmml.classList.add('copied');
        showToast('已複製數學公式！在 Word 中按 Ctrl+V 即可貼入原生方程式。');
        setTimeout(() => {
          btnCopyOmml.innerHTML = '<i class="fa-solid fa-copy"></i> 複製數學公式';
          btnCopyOmml.classList.remove('copied');
        }, 2200);
      }).catch(() => {
        copyFallback(lesson.omml_xml);
      });
    } else {
      copyFallback(lesson.omml_xml);
    }
  };

  function copyFallback(text) {
    const ta = document.createElement('textarea');
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast('已複製數學公式代碼！');
  }

  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (e.key === 'ArrowLeft') {
      if (currentWeek > 1) loadWeek(currentWeek - 1);
    } else if (e.key === 'ArrowRight') {
      if (currentWeek < 30) loadWeek(currentWeek + 1);
    } else if (e.key.toLowerCase() === 'r') {
      const resetBtn = document.getElementById('btnResetExp');
      if (resetBtn) resetBtn.click();
    } else if (e.key.toLowerCase() === 'c') {
      cerCard.classList.toggle('collapsed');
    }
  });

  document.getElementById('btnClearTable').onclick = () => {
    recordedTables[currentWeek] = [];
    renderObservationTable(LESSONS_DATA[currentWeek - 1]);
    showToast('觀測表已清空');
  };

  document.getElementById('btnRecordData').onclick = () => {
    recordCurrentData();
  };
}

// Load Week
function loadWeek(week) {
  if (animationFrameId) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }

  currentWeek = week;
  weekSelect.value = week;
  btnPrevWeek.disabled = (week === 1);
  btnNextWeek.disabled = (week === 30);

  const lesson = LESSONS_DATA[week - 1];

  // Banner
  document.getElementById('bannerWeek').textContent = `第 ${String(lesson.week).padStart(2, '0')} 週`;
  document.getElementById('bannerDomain').textContent = lesson.domain;
  document.getElementById('bannerUnit').textContent = lesson.unit;
  document.getElementById('bannerTitle').textContent = lesson.title;
  document.getElementById('bannerCoords').textContent = lesson.pisa_coords;

  // Context & Guide (with MathJax math formatting)
  document.getElementById('contextText').innerHTML = lesson.text_scrutiny;
  document.getElementById('misconceptionText').innerHTML = lesson.misconception;
  document.getElementById('expPrinciple').innerHTML = `★ 實驗原理：${lesson.exp_principle}`;

  const stepsList = document.getElementById('expStepsList');
  stepsList.innerHTML = '';
  lesson.exp_steps.forEach(st => {
    const li = document.createElement('li');
    li.innerHTML = st;
    stepsList.appendChild(li);
  });

  // Kid-Friendly Math Courtroom (CER)
  document.getElementById('cerClaim').innerHTML = lesson.cer.claim;
  document.getElementById('cerEvidence').innerHTML = lesson.cer.evidence;
  document.getElementById('cerReasoning').innerHTML = lesson.cer.reasoning;
  document.getElementById('cerRebuttal').innerHTML = lesson.cer.rebuttal;
  cerCard.classList.add('collapsed');

  // Solution Box Reset
  if (solutionBox) {
    solutionBox.style.display = 'none';
    solutionBtnText.textContent = '查看參考解答與思維解析';
    btnToggleSolution.classList.remove('active');
    solutionContent.innerHTML = lesson.cps_solution;
  }

  // Core Math Model (Clean Title & Formula)
  ommlTitleEl.textContent = `本課核心數學模型 · ${lesson.omml_title}`;
  mathjaxFormulaEl.innerHTML = `$$\\displaystyle ${lesson.tex_formula}$$`;
  ommlXmlText.value = lesson.omml_xml;

  // CPS Challenge
  document.getElementById('cpsChallengeText').innerHTML = lesson.cps_challenge;

  // Sandbox Name
  document.getElementById('sandboxName').textContent = lesson.exp_name;

  // Update Observation Table
  if (!recordedTables[week]) {
    recordedTables[week] = JSON.parse(JSON.stringify(lesson.table_rows));
  }
  renderObservationTable(lesson);

  // Update active sidebar item
  populateSidebar();

  // Mount specific experiment
  mountExperiment(week);

  // Typeset all math formulas on the page with MathJax
  if (window.MathJax && window.MathJax.typesetPromise) {
    MathJax.typesetPromise([
      document.querySelector('.panel-left'),
      mathjaxFormulaEl
    ]).catch(() => {});
  }
}

// Render Observation Table
function renderObservationTable(lesson) {
  const thead = document.getElementById('obsThead');
  const tbody = document.getElementById('obsTbody');

  thead.innerHTML = '<tr>' + lesson.table_headers.map(h => `<th>${h}</th>`).join('') + '</tr>';

  const rows = recordedTables[lesson.week] || [];
  tbody.innerHTML = rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('');
}

// Record current experiment parameters to table
let currentRecordGetter = null;
function recordCurrentData() {
  if (currentRecordGetter) {
    const newRow = currentRecordGetter();
    if (newRow) {
      recordedTables[currentWeek].push(newRow);
      renderObservationTable(LESSONS_DATA[currentWeek - 1]);
      showToast('✔ 已記錄一組實驗數據至觀測表！');
    }
  } else {
    showToast('當前實驗台暫無自訂數據採集器');
  }
}

// Router to mount experiment by week
function mountExperiment(week) {
  const controlsEl = document.getElementById('sandboxControls');
  const canvas = document.getElementById('mainCanvas');
  const ctx = canvas.getContext('2d');
  const readoutEl = document.getElementById('sandboxReadout');
  const resetBtn = document.getElementById('btnResetExp');

  controlsEl.innerHTML = '';
  readoutEl.innerHTML = '';
  currentRecordGetter = null;

  const fnName = `initExp_W${week}`;
  if (typeof window[fnName] === 'function') {
    window[fnName](controlsEl, canvas, ctx, readoutEl, resetBtn);
  } else {
    controlsEl.innerHTML = `<p style="padding:15px; color:#64748b;">實驗模組就緒中...</p>`;
  }
}



// ============================================================================
// BESPOKE INTERACTIVE EXPERIMENT MODULES FOR ALL 30 WEEKS
// ============================================================================

// ----------------------------------------------------------------------------
// Week 1: 果汁濃度與比值的本質 (Ratio & Concentration)
// ----------------------------------------------------------------------------
window.initExp_W1 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>濃縮果汁 (份)</span><span id="vJuice" class="control-val">1</span></div>
      <input type="range" id="slJuice" class="control-slider" min="1" max="5" value="1">
    </div>
    <div class="control-group">
      <div class="control-label"><span>清水份數 (份)</span><span id="vWater" class="control-val">2</span></div>
      <input type="range" id="slWater" class="control-slider" min="1" max="10" value="2">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle" onclick="setPreset_W1(1, 2)">標籤 A (1:2)</button>
      <button class="btn-toggle" onclick="setPreset_W1(1, 4)">標籤 B (1:4)</button>
      <button class="btn-toggle" onclick="setPreset_W1(1, 5)">標籤 C (1:5)</button>
    </div>
  `;

  let juice = 1, water = 2;
  window.setPreset_W1 = (j, w) => {
    document.getElementById('slJuice').value = j;
    document.getElementById('slWater').value = w;
    update();
  };

  function update() {
    juice = parseInt(document.getElementById('slJuice').value);
    water = parseInt(document.getElementById('slWater').value);
    document.getElementById('vJuice').textContent = juice;
    document.getElementById('vWater').textContent = water;

    const total = juice + water;
    const ratioVal = (juice / water).toFixed(2);
    const concPercent = ((juice / total) * 100).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBeaker(ctx, 120, 320, 1, 2, 'A款 (1:2)', '0.50', '33.3%');
    drawBeaker(ctx, 270, 320, 1, 4, 'B款 (1:4)', '0.25', '20.0%');
    drawBeaker(ctx, 420, 320, 1, 5, 'C款 (1:5)', '0.20', '16.7%');
    drawBeaker(ctx, 580, 320, juice, water, `當前 (${juice}:${water})`, ratioVal, concPercent + '%', true);

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">配比:</span><span class="readout-val">${juice} : ${water}</span></div>
      <div class="readout-item"><span class="readout-lbl">比值 (前÷後):</span><span class="readout-val highlight">${ratioVal}</span></div>
      <div class="readout-item"><span class="readout-lbl">整體百分比濃度:</span><span class="readout-val success">${concPercent}%</span></div>
      <div class="readout-item"><span class="readout-lbl">口感評判:</span><span class="readout-val">${juice/water >= 0.4 ? '濃郁甘甜' : (juice/water >= 0.22 ? '適中清新' : '偏淡如水')}</span></div>
    `;

    currentRecordGetter = () => [
      `調配組 (${juice}:${water})`, `${juice} : ${water}`, `${juice}÷${water} = ${ratioVal}`, `${total} 份`, `${concPercent}%`, juice/water >= 0.4 ? '深橙色' : '淺橙黃色'
    ];
  }

  function drawBeaker(c, x, y, j, w, label, rVal, pVal, isCur = false) {
    const bw = 90, bh = 200;
    c.save();
    c.lineWidth = isCur ? 3 : 2;
    c.strokeStyle = isCur ? '#2563eb' : '#475569';
    c.strokeRect(x - bw/2, y - bh, bw, bh);

    const conc = j / (j + w);
    const fillH = Math.min(bh - 10, (j + w) * 16);
    const r = 255;
    const g = Math.floor(180 - conc * 120);
    const b = 20;
    c.fillStyle = `rgb(${r}, ${g}, ${b})`;
    c.fillRect(x - bw/2 + 2, y - fillH, bw - 4, fillH);

    c.fillStyle = isCur ? '#1e40af' : '#1e293b';
    c.font = isCur ? 'bold 13px sans-serif' : '12px sans-serif';
    c.textAlign = 'center';
    c.fillText(label, x, y + 22);
    c.font = '11px sans-serif';
    c.fillStyle = '#64748b';
    c.fillText(`比值: ${rVal}`, x, y + 38);
    c.fillText(`濃度: ${pVal}`, x, y + 54);
    c.restore();
  }

  document.getElementById('slJuice').oninput = update;
  document.getElementById('slWater').oninput = update;
  resetBtn.onclick = () => window.setPreset_W1(1, 2);
  update();
};

// ----------------------------------------------------------------------------
// Week 2: 防疫消毒液配製比例 (1:99 & Proportional Allocation)
// ----------------------------------------------------------------------------
window.initExp_W2 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>消毒桶總容量 (mL)</span><span id="vVol" class="control-val">5000</span></div>
      <input type="range" id="slVol" class="control-slider" min="500" max="10000" step="500" value="5000">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="btnM1">1:99 日常消毒</button>
      <button class="btn-toggle" id="btnM2">1:49 應急消殺</button>
      <button class="btn-toggle" id="btnM3">1:120 過度稀釋</button>
    </div>
  `;

  let totalVol = 5000, ratioN = 99;
  const slVol = document.getElementById('slVol');
  const b1 = document.getElementById('btnM1'), b2 = document.getElementById('btnM2'), b3 = document.getElementById('btnM3');

  function setMode(n, btn) {
    ratioN = n;
    [b1, b2, b3].forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    update();
  }
  b1.onclick = () => setMode(99, b1);
  b2.onclick = () => setMode(49, b2);
  b3.onclick = () => setMode(120, b3);

  function update() {
    totalVol = parseInt(slVol.value);
    document.getElementById('vVol').textContent = totalVol;

    const totalParts = 1 + ratioN;
    const bleach = (totalVol / totalParts).toFixed(1);
    const water = (totalVol - bleach).toFixed(1);
    const ppm = Math.round((bleach / totalVol) * 50000);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 3;
    ctx.strokeRect(140, 90, 180, 240);
    ctx.fillStyle = '#bae6fd';
    ctx.fillRect(142, 110, 176, 218);
    ctx.fillStyle = '#fde047';
    ctx.fillRect(142, 305, 176, 23);

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText(`配製比例 1 : ${ratioN}`, 380, 120);
    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#b45309';
    ctx.fillText(`漂白水原液需求: ${bleach} mL (1 份)`, 380, 160);
    ctx.fillStyle = '#0284c7';
    ctx.fillText(`清水添加體積: ${water} mL (${ratioN} 份)`, 380, 195);
    ctx.fillStyle = '#475569';
    ctx.fillText(`有效氯濃度估算: ~${ppm} ppm`, 380, 230);

    let statusText = '✔ 符合衛生局防護規範 (有效殺菌)';
    let statusColor = '#16a34a';
    if (ratioN === 120) {
      statusText = '✘ 稀釋過度！濃度低於 400ppm 無法滅毒';
      statusColor = '#dc2626';
    } else if (ratioN === 49) {
      statusText = '★ 高濃度應急消殺，使用需開窗通風';
      statusColor = '#ea580c';
    }
    ctx.fillStyle = statusColor;
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(statusText, 380, 275);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總容量:</span><span class="readout-val">${totalVol} mL</span></div>
      <div class="readout-item"><span class="readout-lbl">原液:</span><span class="readout-val highlight">${bleach} mL</span></div>
      <div class="readout-item"><span class="readout-lbl">清水:</span><span class="readout-val">${water} mL</span></div>
      <div class="readout-item"><span class="readout-lbl">消殺評級:</span><span class="readout-val ${ratioN===120?'danger':'success'}">${statusText}</span></div>
    `;

    currentRecordGetter = () => [
      `調配組 (${totalVol}mL / 1:${ratioN})`, `1 : ${ratioN}`, `${totalParts} 份`, `${totalVol} mL`, `${bleach} mL`, `${water} mL`
    ];
  }

  slVol.oninput = update;
  resetBtn.onclick = () => { slVol.value = 5000; b1.click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 3: 分數除法幾何裁切 (Fraction Division on Number Line)
// ----------------------------------------------------------------------------
window.initExp_W3 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>綵帶總長度 a (米)</span><span id="vLen" class="control-val">3</span></div>
      <input type="range" id="slLen" class="control-slider" min="1" max="5" value="3">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bFrac1">1/2 米</button>
      <button class="btn-toggle" id="bFrac2">3/4 米</button>
      <button class="btn-toggle" id="bFrac3">1/4 米</button>
      <button class="btn-toggle" id="bFrac4">2/3 米</button>
    </div>
  `;

  let totalLen = 3, segLen = 0.5, fracLabel = '1/2';
  const slLen = document.getElementById('slLen');
  const btns = [document.getElementById('bFrac1'), document.getElementById('bFrac2'), document.getElementById('bFrac3'), document.getElementById('bFrac4')];

  function setSeg(val, lbl, btn) {
    segLen = val; fracLabel = lbl;
    btns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    update();
  }
  btns[0].onclick = () => setSeg(0.5, '1/2', btns[0]);
  btns[1].onclick = () => setSeg(0.75, '3/4', btns[1]);
  btns[2].onclick = () => setSeg(0.25, '1/4', btns[2]);
  btns[3].onclick = () => setSeg(2/3, '2/3', btns[3]);

  function update() {
    totalLen = parseInt(slLen.value);
    document.getElementById('vLen').textContent = totalLen;

    const exactSegs = totalLen / segLen;
    const fullSegs = Math.floor(exactSegs);
    const rem = (totalLen - fullSegs * segLen).toFixed(2);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Draw main ribbon
    const startX = 60, startY = 130, maxW = 580;
    const pxPerM = maxW / 5;

    ctx.fillStyle = '#64748b';
    ctx.font = '14px sans-serif';
    ctx.fillText(`綵帶總長度度量線 (${totalLen} 米):`, startX, startY - 20);

    ctx.fillStyle = '#e2e8f0';
    ctx.fillRect(startX, startY, totalLen * pxPerM, 40);
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 2;
    ctx.strokeRect(startX, startY, totalLen * pxPerM, 40);

    // Draw meter marks
    for (let m = 0; m <= totalLen; m++) {
      const mx = startX + m * pxPerM;
      ctx.beginPath();
      ctx.moveTo(mx, startY - 8); ctx.lineTo(mx, startY + 48);
      ctx.strokeStyle = '#0f172a';
      ctx.stroke();
      ctx.fillStyle = '#0f172a';
      ctx.font = 'bold 12px sans-serif';
      ctx.fillText(`${m}m`, mx - 8, startY + 65);
    }

    // Draw cuts
    for (let s = 0; s < fullSegs; s++) {
      const sx = startX + s * segLen * pxPerM;
      const sw = segLen * pxPerM;
      ctx.fillStyle = s % 2 === 0 ? 'rgba(59, 130, 246, 0.45)' : 'rgba(16, 185, 129, 0.45)';
      ctx.fillRect(sx + 1, startY + 2, sw - 2, 36);

      ctx.strokeStyle = '#dc2626';
      ctx.setLineDash([4, 2]);
      ctx.beginPath();
      ctx.moveTo(sx + sw, startY - 5); ctx.lineTo(sx + sw, startY + 45);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = '#1e3a8a';
      ctx.font = '11px sans-serif';
      ctx.fillText(`第${s+1}段`, sx + sw/2 - 12, startY + 24);
    }

    // Explanation
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`幾何度量模型: ${totalLen} ÷ (${fracLabel}) = ${totalLen} × (${(1/segLen).toFixed(2)}) = ${exactSegs.toFixed(2)} 段`, startX, 260);

    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#15803d';
    ctx.fillText(`✔ 倒數本質：1米內包含 ${(1/segLen).toFixed(2)} 段標尺，故 ${totalLen} 米包含 ${totalLen} × ${(1/segLen).toFixed(2)} 段。`, startX, 290);
    ctx.fillStyle = '#b45309';
    ctx.fillText(`★ 完整裁出: ${fullSegs} 段${rem > 0 ? `，剩餘邊角料: ${rem} 米` : ' (恰好裁盡無剩餘)'}`, startX, 315);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總長:</span><span class="readout-val">${totalLen} 米</span></div>
      <div class="readout-item"><span class="readout-lbl">每段尺碼:</span><span class="readout-val">${fracLabel} 米</span></div>
      <div class="readout-item"><span class="readout-lbl">裁切總段數:</span><span class="readout-val highlight">${exactSegs.toFixed(2)} 段</span></div>
      <div class="readout-item"><span class="readout-lbl">完整段數:</span><span class="readout-val success">${fullSegs} 段整</span></div>
    `;

    currentRecordGetter = () => [
      `${totalLen} 米`, `${fracLabel} 米`, `${(1/segLen).toFixed(2)} 段`, `${exactSegs.toFixed(2)} 段`, `${totalLen} × ${(1/segLen).toFixed(2)} = ${exactSegs.toFixed(2)}`, exactSegs > totalLen ? '商 > 被除數' : '商 ≤ 被除數'
    ];
  }

  slLen.oninput = update;
  resetBtn.onclick = () => { slLen.value = 3; btns[0].click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 4: 合作工程與工作效率疊加 (Work Efficiency Synthesis)
// ----------------------------------------------------------------------------
window.initExp_W4 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>甲隊獨做天數 (天)</span><span id="vDayA" class="control-val">6</span></div>
      <input type="range" id="slDayA" class="control-slider" min="2" max="20" value="6">
    </div>
    <div class="control-group">
      <div class="control-label"><span>乙隊獨做天數 (天)</span><span id="vDayB" class="control-val">12</span></div>
      <input type="range" id="slDayB" class="control-slider" min="2" max="30" value="12">
    </div>
  `;

  const slA = document.getElementById('slDayA'), slB = document.getElementById('slDayB');

  function update() {
    const a = parseInt(slA.value), b = parseInt(slB.value);
    document.getElementById('vDayA').textContent = a;
    document.getElementById('vDayB').textContent = b;

    const effA = 1 / a, effB = 1 / b;
    const effTot = effA + effB;
    const realDays = (1 / effTot).toFixed(2);
    const wrongAvg = ((a + b) / 2).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Draw efficiency bars
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('每日工程產能對比 (每日完成總工程的比例):', 50, 45);

    // Bar A
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(150, 75, effA * 600, 24);
    ctx.fillStyle = '#1e293b';
    ctx.font = '13px sans-serif';
    ctx.fillText(`甲隊 (1/${a}): ${(effA*100).toFixed(1)}%/天`, 20, 92);

    // Bar B
    ctx.fillStyle = '#10b981';
    ctx.fillRect(150, 115, effB * 600, 24);
    ctx.fillStyle = '#1e293b';
    ctx.fillText(`乙隊 (1/${b}): ${(effB*100).toFixed(1)}%/天`, 20, 132);

    // Combined
    ctx.fillStyle = '#8b5cf6';
    ctx.fillRect(150, 155, effTot * 600, 28);
    ctx.fillStyle = '#4c1d95';
    ctx.font = 'bold 13px sans-serif';
    ctx.fillText(`合作疊加 (1/${a} + 1/${b}): ${(effTot*100).toFixed(1)}%/天`, 20, 174);

    // Summary Comparison Box
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(50, 215, 600, 120);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(50, 215, 600, 120);

    ctx.fillStyle = '#15803d';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText(`✔ 真實合作工期: 1 ÷ (1/${a} + 1/${b}) = ${realDays} 天 (工效疊加，耗時劇減)`, 70, 255);

    ctx.fillStyle = '#dc2626';
    ctx.font = '14px sans-serif';
    ctx.fillText(`✘ 錯誤直覺平均: (${a} + ${b}) ÷ 2 = ${wrongAvg} 天 (荒謬！越幫忙完工反而越慢？)`, 70, 290);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">甲隊工效:</span><span class="readout-val">1/${a}</span></div>
      <div class="readout-item"><span class="readout-lbl">乙隊工效:</span><span class="readout-val">1/${b}</span></div>
      <div class="readout-item"><span class="readout-lbl">真實合作天數:</span><span class="readout-val success">${realDays} 天</span></div>
      <div class="readout-item"><span class="readout-lbl">錯誤直覺天數:</span><span class="readout-val danger">${wrongAvg} 天</span></div>
    `;

    currentRecordGetter = () => [
      `方案 (甲${a}天 + 乙${b}天)`, `${a} 天`, `${b} 天`, `1/${a}`, `1/${b}`, `1/${a}+1/${b} = ${effTot.toFixed(3)}`, `${realDays} 天`, `${wrongAvg} 天 (錯)`
    ];
  }

  slA.oninput = update; slB.oninput = update;
  resetBtn.onclick = () => { slA.value = 6; slB.value = 12; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 5: 促銷折算演算法順序沙盒 (Discount Sequence Sandbox)
// ----------------------------------------------------------------------------
window.initExp_W5 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>商品原價 P (元)</span><span id="vPrice" class="control-val">400</span></div>
      <input type="range" id="slPrice" class="control-slider" min="100" max="1000" step="50" value="400">
    </div>
    <div class="control-group">
      <div class="control-label"><span>折扣率 d</span><span id="vDisc" class="control-val">0.8 (八折)</span></div>
      <input type="range" id="slDisc" class="control-slider" min="0.5" max="0.9" step="0.05" value="0.8">
    </div>
    <div class="control-group">
      <div class="control-label"><span>立減金額 M (元)</span><span id="vCoupon" class="control-val">50</span></div>
      <input type="range" id="slCoupon" class="control-slider" min="20" max="100" step="10" value="50">
    </div>
  `;

  const slP = document.getElementById('slPrice'), slD = document.getElementById('slDisc'), slC = document.getElementById('slCoupon');

  function update() {
    const P = parseFloat(slP.value);
    const d = parseFloat(slD.value);
    const M = parseFloat(slC.value);

    document.getElementById('vPrice').textContent = P;
    document.getElementById('vDisc').textContent = `${d} (${Math.round(d*10)}折)`;
    document.getElementById('vCoupon').textContent = M;

    const p1 = Math.max(0, P * d - M); // 先折後減
    const p2 = Math.max(0, (P - M) * d); // 先減後折
    const diff = (p2 - p1).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Draw Receipt 1 (先折後減)
    drawReceipt(ctx, 160, 50, '方案一：先折後減 (顧客最優)', [
      `商品原價: $${P}`,
      `第一步 (打${Math.round(d*10)}折): $${(P*d).toFixed(1)}`,
      `第二步 (滿減扣券): -$${M}`,
      `實付金額: $${p1.toFixed(1)}`
    ], '#16a34a', true);

    // Draw Receipt 2 (先減後折)
    drawReceipt(ctx, 420, 50, '方案二：先減後折 (商家常設)', [
      `商品原價: $${P}`,
      `第一步 (滿減扣券): -$${M} ➔ $${P-M}`,
      `第二步 (打${Math.round(d*10)}折): ×${d}`,
      `實付金額: $${p2.toFixed(1)}`
    ], '#dc2626', false);

    // Bottom banner
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(80, 290, 540, 70);
    ctx.strokeStyle = '#3b82f6';
    ctx.strokeRect(80, 290, 540, 70);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`★ 運算順序審計結論：方案一比方案二省 $${diff} 元！`, 100, 320);
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#64748b';
    ctx.fillText(`數學規律：差額恆等於 立減金額 × (1 - 折扣率) = ${M} × (1 - ${d}) = $${diff} 元。`, 100, 345);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">先折後減:</span><span class="readout-val success">$${p1.toFixed(1)}</span></div>
      <div class="readout-item"><span class="readout-lbl">先減後折:</span><span class="readout-val danger">$${p2.toFixed(1)}</span></div>
      <div class="readout-item"><span class="readout-lbl">節省差額:</span><span class="readout-val highlight">$${diff} 元</span></div>
      <div class="readout-item"><span class="readout-lbl">推薦決策:</span><span class="readout-val">先折後減</span></div>
    `;

    currentRecordGetter = () => [
      `原價$${P}`, `${Math.round(d*10)}折`, `減$${M}`, `$${p1.toFixed(1)}`, `$${p2.toFixed(1)}`, '方案一更省', `省 $${diff} 元`
    ];
  }

  function drawReceipt(c, x, y, title, lines, themeColor, isBest) {
    const rw = 220, rh = 210;
    c.save();
    c.fillStyle = '#ffffff';
    c.fillRect(x, y, rw, rh);
    c.strokeStyle = themeColor;
    c.lineWidth = 2;
    c.strokeRect(x, y, rw, rh);

    c.fillStyle = themeColor;
    c.fillRect(x, y, rw, 32);
    c.fillStyle = '#ffffff';
    c.font = 'bold 13px sans-serif';
    c.textAlign = 'center';
    c.fillText(title, x + rw/2, y + 21);

    c.textAlign = 'left';
    c.font = '13px sans-serif';
    c.fillStyle = '#334155';
    lines.forEach((ln, idx) => {
      const ly = y + 65 + idx * 34;
      if (idx === lines.length - 1) {
        c.font = 'bold 15px sans-serif';
        c.fillStyle = themeColor;
      }
      c.fillText(ln, x + 15, ly);
    });

    if (isBest) {
      c.strokeStyle = '#16a34a';
      c.lineWidth = 2;
      c.strokeRect(x + rw - 70, y + rh - 45, 60, 25);
      c.fillStyle = '#16a34a';
      c.font = 'bold 12px sans-serif';
      c.fillText('✔ 最省', x + rw - 58, y + rh - 28);
    }
    c.restore();
  }

  slP.oninput = update; slD.oninput = update; slC.oninput = update;
  resetBtn.onclick = () => { slP.value = 400; slD.value = 0.8; slC.value = 50; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 6: 公共交通票價結算與進位仲裁 (Rounding in Contexts)
// ----------------------------------------------------------------------------
window.initExp_W6 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>研學乘客人數 P (人)</span><span id="vPass" class="control-val">102</span></div>
      <input type="range" id="slPass" class="control-slider" min="20" max="250" value="102">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="btnB45">45人座大巴</button>
      <button class="btn-toggle" id="btnB30">30人座中巴</button>
      <button class="btn-toggle" id="btnB60">60人座雙層巴</button>
    </div>
  `;

  let pass = 102, cap = 45;
  const slPass = document.getElementById('slPass');
  const b1 = document.getElementById('btnB45'), b2 = document.getElementById('btnB30'), b3 = document.getElementById('btnB60');

  function setCap(c, btn) {
    cap = c;
    [b1, b2, b3].forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    update();
  }
  b1.onclick = () => setCap(45, b1);
  b2.onclick = () => setCap(30, b2);
  b3.onclick = () => setCap(60, b3);

  function update() {
    pass = parseInt(slPass.value);
    document.getElementById('vPass').textContent = pass;

    const rawBuses = pass / cap;
    const ceilBuses = Math.ceil(rawBuses);
    const floorBuses = Math.floor(rawBuses);
    const roundBuses = Math.round(rawBuses);
    const lastBusP = pass % cap === 0 ? cap : (pass % cap);
    const emptySeats = cap - lastBusP;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Roadway
    ctx.fillStyle = '#334155';
    ctx.fillRect(40, 150, 620, 80);
    ctx.setLineDash([15, 10]);
    ctx.strokeStyle = '#facc15';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(40, 190); ctx.lineTo(660, 190); ctx.stroke();
    ctx.setLineDash([]);

    // Draw buses
    const maxDraw = Math.min(ceilBuses, 5);
    for (let i = 0; i < maxDraw; i++) {
      const bx = 60 + i * 115;
      const isLast = (i === ceilBuses - 1);
      ctx.fillStyle = isLast ? '#f59e0b' : '#3b82f6';
      ctx.fillRect(bx, 155, 95, 50);
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(bx + 15, 160, 20, 15);
      ctx.fillRect(bx + 45, 160, 20, 15);

      // Wheels
      ctx.beginPath(); ctx.arc(bx + 25, 205, 8, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(bx + 75, 205, 8, 0, Math.PI*2); ctx.fill();

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 11px sans-serif';
      ctx.fillText(`車${i+1}: ${isLast ? `${lastBusP}人` : `${cap}人滿`}`, bx + 12, 195);
    }

    if (ceilBuses > 5) {
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 14px sans-serif';
      ctx.fillText(`+ 另有 ${ceilBuses - 5} 輛`, 580, 185);
    }

    // Arbitration Cards
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`公共決策仲裁比較 (${pass}人 ÷ ${cap}座/車 = ${rawBuses.toFixed(2)}):`, 50, 50);

    drawVerdict(ctx, 50, 70, `進一法 (Ceil): ${ceilBuses} 輛`, '✔ 唯一安全合規方案 (不可留人在車站)', '#16a34a');
    drawVerdict(ctx, 50, 250, `去尾法 (Floor): ${floorBuses} 輛`, `✘ 嚴重失職！將遺留 ${pass - floorBuses*cap} 名學生無法上車`, '#dc2626');
    drawVerdict(ctx, 350, 250, `四捨五入: ${roundBuses} 輛`, `${roundBuses < ceilBuses ? '✘ 依然會超載或留人' : '▲ 碰巧等於進一法'}`, '#d97706');
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總人數:</span><span class="readout-val">${pass} 人</span></div>
      <div class="readout-item"><span class="readout-lbl">核載:</span><span class="readout-val">${cap} 座</span></div>
      <div class="readout-item"><span class="readout-lbl">租車需求:</span><span class="readout-val success">${ceilBuses} 輛 (進一法)</span></div>
      <div class="readout-item"><span class="readout-lbl">末車空座:</span><span class="readout-val highlight">${emptySeats} 空位</span></div>
    `;

    currentRecordGetter = () => [
      `研學團 ${pass}人`, `${pass} 人`, `${cap} 座`, `${rawBuses.toFixed(2)}`, `${ceilBuses} 輛 (進一法)`, `末車剩 ${emptySeats} 空位`
    ];
  }

  function drawVerdict(c, x, y, title, desc, color) {
    c.save();
    c.fillStyle = color;
    c.font = 'bold 14px sans-serif';
    c.fillText(title, x, y);
    c.fillStyle = '#475569';
    c.font = '12px sans-serif';
    c.fillText(desc, x, y + 18);
    c.restore();
  }

  slPass.oninput = update;
  resetBtn.onclick = () => { slPass.value = 102; b1.click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 7: 家庭階梯電費與碳排放 (Tiered Electricity & Carbon)
// ----------------------------------------------------------------------------
window.initExp_W7 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>月用電量 E (度 / kWh)</span><span id="vElec" class="control-val">280</span></div>
      <input type="range" id="slElec" class="control-slider" min="0" max="600" step="10" value="280">
    </div>
  `;

  const slE = document.getElementById('slElec');

  function update() {
    const E = parseInt(slE.value);
    document.getElementById('vElec').textContent = E;

    let c1 = 0, c2 = 0, c3 = 0;
    if (E <= 200) {
      c1 = E * 1.0;
    } else if (E <= 400) {
      c1 = 200 * 1.0;
      c2 = (E - 200) * 1.5;
    } else {
      c1 = 200 * 1.0;
      c2 = 200 * 1.5;
      c3 = (E - 400) * 2.0;
    }
    const totalCost = (c1 + c2 + c3).toFixed(1);
    const co2 = (E * 0.537).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Draw Tier Buckets
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('階梯電費分檔填充與非線性計費模型:', 50, 45);

    drawBucket(ctx, 80, 80, '第一檔 (0-200度)', Math.min(E, 200), 200, '$1.0/度', '#10b981');
    drawBucket(ctx, 240, 80, '第二檔 (201-400度)', Math.max(0, Math.min(E - 200, 200)), 200, '$1.5/度', '#f59e0b');
    drawBucket(ctx, 400, 80, '第三檔 (>400度)', Math.max(0, E - 400), 200, '$2.0/度', '#ef4444');

    // Summary Card
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(80, 240, 520, 110);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(80, 240, 520, 110);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText(`總電費 = $${c1.toFixed(1)} (檔1) + $${c2.toFixed(1)} (檔2) + $${c3.toFixed(1)} (檔3) = $${totalCost} 元`, 100, 275);

    ctx.fillStyle = '#059669';
    ctx.font = '14px sans-serif';
    ctx.fillText(`🌱 碳足跡評估: 本月產生碳排放約 ${co2} kg CO₂ (係數 0.537 kg/度)`, 100, 305);
    ctx.fillStyle = '#64748b';
    ctx.font = '12px sans-serif';
    ctx.fillText(`節能倡議：將空調調高 1℃ 可減少第 3 檔高價用電，月省約 $30-50 元。`, 100, 330);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總用電:</span><span class="readout-val">${E} 度</span></div>
      <div class="readout-item"><span class="readout-lbl">當前檔位:</span><span class="readout-val ${E>400?'danger':(E>200?'highlight':'success')}">${E>400?'第3檔(高消耗)':(E>200?'第2檔(適度)':'第1檔(綠色)')}</span></div>
      <div class="readout-item"><span class="readout-lbl">應付電費:</span><span class="readout-val highlight">$${totalCost} 元</span></div>
      <div class="readout-item"><span class="readout-lbl">碳排放:</span><span class="readout-val">${co2} kg</span></div>
    `;

    currentRecordGetter = () => [
      `用電 ${E}度`, `${E} kWh`, `$${c1.toFixed(1)}`, `$${c2.toFixed(1)}`, `$${c3.toFixed(1)}`, `$${totalCost} 元`, `${co2} kg CO2`
    ];
  }

  function drawBucket(c, x, y, title, val, maxVal, price, color) {
    const bw = 130, bh = 130;
    c.save();
    c.strokeStyle = '#475569';
    c.strokeRect(x, y + 20, bw, bh);

    const fillRatio = val / maxVal;
    c.fillStyle = color;
    c.fillRect(x + 2, y + 20 + bh * (1 - fillRatio), bw - 4, bh * fillRatio);

    c.fillStyle = '#0f172a';
    c.font = 'bold 12px sans-serif';
    c.textAlign = 'center';
    c.fillText(title, x + bw/2, y + 14);
    c.fillText(`${val}/${maxVal}度`, x + bw/2, y + 20 + bh/2);
    c.font = '11px sans-serif';
    c.fillStyle = '#64748b';
    c.fillText(price, x + bw/2, y + bh + 36);
    c.restore();
  }

  slE.oninput = update;
  resetBtn.onclick = () => { slE.value = 280; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Weeks 8 to 30: Custom-built dedicated interactive models
// ----------------------------------------------------------------------------



// ----------------------------------------------------------------------------
// Week 8: 商業宣傳商品標籤文字陷阱 (Nutritional Label Magnifier)
// ----------------------------------------------------------------------------
window.initExp_W8 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>單份規格 (g)</span><span id="vServe" class="control-val">30</span></div>
      <input type="range" id="slServe" class="control-slider" min="15" max="60" step="5" value="30">
    </div>
    <div class="control-group">
      <div class="control-label"><span>整瓶淨含量 (g)</span><span id="vBottle" class="control-val">500</span></div>
      <input type="range" id="slBottle" class="control-slider" min="200" max="1000" step="50" value="500">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="btnModeAd">廣告宣傳視角</button>
      <button class="btn-toggle" id="btnModeTruth">真相審查視角</button>
    </div>
  `;

  let serve = 30, bottle = 500, mode = 'ad';
  const slS = document.getElementById('slServe'), slB = document.getElementById('slBottle');
  const bAd = document.getElementById('btnModeAd'), bTr = document.getElementById('btnModeTruth');

  bAd.onclick = () => { mode = 'ad'; bAd.classList.add('active'); bTr.classList.remove('active'); update(); };
  bTr.onclick = () => { mode = 'truth'; bTr.classList.add('active'); bAd.classList.remove('active'); update(); };

  function update() {
    serve = parseInt(slS.value);
    bottle = parseInt(slB.value);
    document.getElementById('vServe').textContent = serve;
    document.getElementById('vBottle').textContent = bottle;

    const sugarPerServe = 4.5; // g
    const servingsCount = (bottle / serve).toFixed(1);
    const totalSugar = (sugarPerServe * (bottle / serve)).toFixed(1);
    const sugarCubes = (totalSugar / 4.5).toFixed(0);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Draw Nutrition Label Card
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(60, 60, 240, 260);
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 3;
    ctx.strokeRect(60, 60, 240, 260);

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 18px sans-serif';
    ctx.fillText('Nutrition Facts', 75, 90);
    ctx.font = '12px sans-serif';
    ctx.fillText(`每瓶容量: ${bottle}g | 每份基準: ${serve}g`, 75, 115);
    ctx.fillText(`包含份數: 約 ${servingsCount} 份`, 75, 135);

    ctx.fillRect(75, 145, 210, 4);

    ctx.font = '14px sans-serif';
    ctx.fillText('每份含糖量: 4.5g', 75, 175);
    ctx.fillText('脂肪: 0g (宣稱零脂)', 75, 205);
    ctx.fillText('能量: 180 kJ / 份', 75, 235);

    // Magnifying Truth Inspection Side
    if (mode === 'truth') {
      ctx.fillStyle = '#fef2f2';
      ctx.fillRect(340, 60, 310, 260);
      ctx.strokeStyle = '#ef4444';
      ctx.strokeRect(340, 60, 310, 260);

      ctx.fillStyle = '#b91c1c';
      ctx.font = 'bold 16px sans-serif';
      ctx.fillText('🔍 媒體素養放大鏡：整瓶真相', 355, 90);

      ctx.fillStyle = '#0f172a';
      ctx.font = '14px sans-serif';
      ctx.fillText(`整瓶實際糖分總量: ${totalSugar} 克！`, 355, 130);
      ctx.fillText(`相當於一口氣吃下 ${sugarCubes} 塊方糖！`, 355, 160);

      // Draw sugar cubes
      ctx.fillStyle = '#cbd5e1';
      ctx.strokeStyle = '#64748b';
      const numCubes = Math.min(parseInt(sugarCubes), 18);
      for (let i = 0; i < numCubes; i++) {
        const cx = 355 + (i % 6) * 35;
        const cy = 190 + Math.floor(i / 6) * 30;
        ctx.fillRect(cx, cy, 28, 22);
        ctx.strokeRect(cx, cy, 28, 22);
      }

      ctx.fillStyle = '#dc2626';
      ctx.font = 'bold 13px sans-serif';
      ctx.fillText('⚠️ 嚴重超標：已達兒童每日糖攝入上限 180%', 355, 295);
    } else {
      ctx.fillStyle = '#f0fdf4';
      ctx.fillRect(340, 60, 310, 260);
      ctx.strokeStyle = '#22c55e';
      ctx.strokeRect(340, 60, 310, 260);

      ctx.fillStyle = '#15803d';
      ctx.font = 'bold 16px sans-serif';
      ctx.fillText('📢 商家廣告宣傳包裝：', 355, 90);
      ctx.font = '14px sans-serif';
      ctx.fillStyle = '#1e293b';
      ctx.fillText('「每份僅含 4.5g 糖，低糖零脂健康首選」', 355, 130);
      ctx.fillStyle = '#64748b';
      ctx.fillText('偷換概念：故意將每份縮小為一口大小', 355, 165);
      ctx.fillText('消費者通常一次喝完整瓶，攝入超標 10 倍！', 355, 195);
      ctx.fillStyle = '#2563eb';
      ctx.font = 'bold 13px sans-serif';
      ctx.fillText('👉 點擊上方按鈕「真相審查視角」進行破解', 355, 260);
    }
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">整瓶淨重:</span><span class="readout-val">${bottle}g</span></div>
      <div class="readout-item"><span class="readout-lbl">總份數:</span><span class="readout-val">${servingsCount} 份</span></div>
      <div class="readout-item"><span class="readout-lbl">整瓶含糖量:</span><span class="readout-val danger">${totalSugar}g</span></div>
      <div class="readout-item"><span class="readout-lbl">折合方糖:</span><span class="readout-val highlight">${sugarCubes} 塊</span></div>
    `;

    currentRecordGetter = () => [
      `規格 ${bottle}g (份${serve}g)`, `${bottle}g`, `${serve}g`, `${servingsCount} 份`, '4.5g / 份', `${totalSugar}g`, `${sugarCubes} 塊方糖`
    ];
  }

  slS.oninput = update; slB.oninput = update;
  resetBtn.onclick = () => { slS.value = 30; slB.value = 500; bAd.click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 9: 澳門格蘭披治大賽車過彎勝率 (Cornering Speed & Centripetal Acceleration)
// ----------------------------------------------------------------------------
window.initExp_W9 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>入彎時速 v (km/h)</span><span id="vSpeed" class="control-val">75</span></div>
      <input type="range" id="slSpeed" class="control-slider" min="40" max="150" step="5" value="75">
    </div>
    <div class="control-group">
      <div class="control-label"><span>過彎半徑 R (m)</span><span id="vRadius" class="control-val">25</span></div>
      <input type="range" id="slRadius" class="control-slider" min="15" max="50" step="5" value="25">
    </div>
  `;

  const slV = document.getElementById('slSpeed'), slR = document.getElementById('slRadius');

  function update() {
    const v = parseInt(slV.value);
    const r = parseInt(slR.value);
    document.getElementById('vSpeed').textContent = v;
    document.getElementById('vRadius').textContent = r;

    // a = v^2 / r in m/s^2
    const v_ms = v / 3.6;
    const accel = (v_ms * v_ms / r).toFixed(1);
    const maxSafeAccel = 12.0; // m/s^2 threshold for grip
    const isSafe = (parseFloat(accel) <= maxSafeAccel);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Racetrack bend
    const ox = 320, oy = 350;
    ctx.lineWidth = 45;
    ctx.strokeStyle = '#475569';
    ctx.beginPath();
    ctx.arc(ox, oy, r * 5, Math.PI, 1.5 * Math.PI, false);
    ctx.stroke();

    // Curbs
    ctx.lineWidth = 6;
    ctx.strokeStyle = '#ef4444';
    ctx.setLineDash([8, 8]);
    ctx.beginPath();
    ctx.arc(ox, oy, r * 5 - 24, Math.PI, 1.5 * Math.PI, false);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(ox, oy, r * 5 + 24, Math.PI, 1.5 * Math.PI, false);
    ctx.stroke();
    ctx.setLineDash([]);

    // Racing car
    const carAngle = Math.PI * 1.25;
    const carR = isSafe ? (r * 5) : (r * 5 + 35);
    const cx = ox + Math.cos(carAngle) * carR;
    const cy = oy + Math.sin(carAngle) * carR;

    ctx.fillStyle = isSafe ? '#22c55e' : '#dc2626';
    ctx.fillRect(cx - 15, cy - 10, 30, 20);

    // Car vector
    ctx.strokeStyle = isSafe ? '#15803d' : '#991b1b';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx - 30, cy - 25); ctx.stroke();

    // HUD Text
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`澳門葡京彎過彎物理模型 (R = ${r}m, v = ${v} km/h):`, 40, 45);

    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#334155';
    ctx.fillText(`向心加速度 a = v² / R = (${(v_ms).toFixed(1)} m/s)² ÷ ${r}m = ${accel} m/s²`, 40, 75);

    let verdict = isSafe ? '✔ 抓地良好：平穩通過彎心 (勝率 85%)' : '✘ 輪胎突破抓地極限！失控推頭打滑衝撞護欄 (勝率 0%)';
    ctx.fillStyle = isSafe ? '#16a34a' : '#dc2626';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(verdict, 40, 105);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">入彎速度:</span><span class="readout-val">${v} km/h</span></div>
      <div class="readout-item"><span class="readout-lbl">半徑 R:</span><span class="readout-val">${r} m</span></div>
      <div class="readout-item"><span class="readout-lbl">向心加速度:</span><span class="readout-val highlight">${accel} m/s²</span></div>
      <div class="readout-item"><span class="readout-lbl">過彎狀態:</span><span class="readout-val ${isSafe?'success':'danger'}">${isSafe?'完美走線':'失控打滑'}</span></div>
    `;

    currentRecordGetter = () => [
      `過彎測試 (${v}km/h)`, `${v} km/h`, `${r} 米`, `${accel} m/s²`, isSafe ? '安全過彎' : '打滑撞牆', isSafe ? '85%' : '0%'
    ];
  }

  slV.oninput = update; slR.oninput = update;
  resetBtn.onclick = () => { slV.value = 75; slR.value = 25; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 10: 正方體 11 種展開圖摺疊 (Cube Nets 3D Folding)
// ----------------------------------------------------------------------------
window.initExp_W10 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>折疊進度</span><span id="vFold" class="control-val">0%</span></div>
      <input type="range" id="slFold" class="control-slider" min="0" max="100" value="0">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bNet1">1-4-1 標準型</button>
      <button class="btn-toggle" id="bNet2">2-3-1 型</button>
      <button class="btn-toggle" id="bNet3">2-2-2 階梯型</button>
      <button class="btn-toggle" id="bNet4">3-3 兩階型</button>
      <button class="btn-toggle" id="bNet5">錯誤田字格(無效)</button>
    </div>
  `;

  let fold = 0, currentType = 1;
  const slF = document.getElementById('slFold');
  const b1 = document.getElementById('bNet1'), b2 = document.getElementById('bNet2'), b3 = document.getElementById('bNet3'), b4 = document.getElementById('bNet4'), b5 = document.getElementById('bNet5');

  function setType(t, btn) {
    currentType = t;
    [b1, b2, b3, b4, b5].forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    update();
  }
  b1.onclick = () => setType(1, b1);
  b2.onclick = () => setType(2, b2);
  b3.onclick = () => setType(3, b3);
  b4.onclick = () => setType(4, b4);
  b5.onclick = () => setType(5, b5);

  function update() {
    fold = parseInt(slF.value);
    document.getElementById('vFold').textContent = `${fold}%`;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    const sq = 46;
    const ox = 120, oy = 100;

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('正方體展開圖平面幾何構型與空間對立面配對:', 40, 45);

    // Render different nets based on type
    let squares = [];
    let isValid = true;
    if (currentType === 1) { // 1-4-1
      squares = [
        {c:1, r:0, color:'#ef4444', label:'上'},
        {c:0, r:1, color:'#3b82f6', label:'左'},
        {c:1, r:1, color:'#10b981', label:'前'},
        {c:2, r:1, color:'#3b82f6', label:'右'},
        {c:3, r:1, color:'#10b981', label:'後'},
        {c:1, r:2, color:'#ef4444', label:'下'}
      ];
    } else if (currentType === 2) { // 2-3-1
      squares = [
        {c:0, r:0, color:'#ef4444', label:'A'},
        {c:1, r:0, color:'#3b82f6', label:'B'},
        {c:1, r:1, color:'#10b981', label:'C'},
        {c:2, r:1, color:'#ef4444', label:'A*'},
        {c:3, r:1, color:'#3b82f6', label:'B*'},
        {c:3, r:2, color:'#10b981', label:'C*'}
      ];
    } else if (currentType === 3) { // 2-2-2
      squares = [
        {c:0, r:0, color:'#f59e0b', label:'1'},
        {c:1, r:0, color:'#6366f1', label:'2'},
        {c:1, r:1, color:'#f59e0b', label:'1*'},
        {c:2, r:1, color:'#ec4899', label:'3'},
        {c:2, r:2, color:'#6366f1', label:'2*'},
        {c:3, r:2, color:'#ec4899', label:'3*'}
      ];
    } else if (currentType === 4) { // 3-3
      squares = [
        {c:0, r:0, color:'#06b6d4', label:'X'},
        {c:1, r:0, color:'#84cc16', label:'Y'},
        {c:2, r:0, color:'#f43f5e', label:'Z'},
        {c:1, r:1, color:'#06b6d4', label:'X*'},
        {c:2, r:1, color:'#84cc16', label:'Y*'},
        {c:3, r:1, color:'#f43f5e', label:'Z*'}
      ];
    } else { // Invalid 田字格
      squares = [
        {c:0, r:0, color:'#94a3b8', label:'重'},
        {c:1, r:0, color:'#94a3b8', label:'重'},
        {c:0, r:1, color:'#94a3b8', label:'重'},
        {c:1, r:1, color:'#94a3b8', label:'重'},
        {c:2, r:1, color:'#cbd5e1', label:'5'},
        {c:3, r:1, color:'#cbd5e1', label:'6'}
      ];
      isValid = false;
    }

    // Draw the squares
    squares.forEach(s => {
      const sx = ox + s.c * sq;
      const sy = oy + s.r * sq;
      ctx.fillStyle = s.color;
      ctx.fillRect(sx, sy, sq, sq);
      ctx.strokeStyle = '#0f172a';
      ctx.lineWidth = 2;
      ctx.strokeRect(sx, sy, sq, sq);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(s.label, sx + sq/2, sy + sq/2 + 5);
    });

    // 3D Isometric Preview Box on Right
    const px = 450, py = 180;
    ctx.strokeStyle = isValid ? '#2563eb' : '#dc2626';
    ctx.lineWidth = 3;
    drawIsometricCube(ctx, px, py, 60, fold / 100, isValid);

    // Annotation
    ctx.textAlign = 'left';
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#1e293b';
    ctx.fillText('★ 對立面識別規律：相同顏色或標記（如 A 與 A*）折疊後必在相對兩側。', 40, 310);
    ctx.fillStyle = isValid ? '#16a34a' : '#dc2626';
    ctx.font = 'bold 14px sans-serif';
    ctx.fillText(isValid ? '✔ 有效展開圖：折疊時 6 個面恰好無縫閉合為正方體' : '✘ 無效展開圖：出現田字格，折疊時面發生重疊碰撞，無法成方！', 40, 340);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">構型類型:</span><span class="readout-val">${b1.classList.contains('active')?'1-4-1':(b2.classList.contains('active')?'2-3-1':(b3.classList.contains('active')?'2-2-2':(b4.classList.contains('active')?'3-3':'田字格')))}</span></div>
      <div class="readout-item"><span class="readout-lbl">折疊進度:</span><span class="readout-val">${fold}%</span></div>
      <div class="readout-item"><span class="readout-lbl">能否圍成正方體:</span><span class="readout-val ${isValid?'success':'danger'}">${isValid?'✔ 可以成方':'✘ 無法成方'}</span></div>
    `;

    currentRecordGetter = () => [
      `構型 ${currentType}`, currentType === 5 ? '田字格 (無效)' : '標準 11 種之一', '6 個面', isValid ? '相隔一格為對立面' : '面重疊', isValid ? '可折疊' : '無法成方'
    ];
  }

  function drawIsometricCube(c, x, y, s, progress, valid) {
    c.save();
    if (!valid) {
      c.fillStyle = '#fee2e2';
      c.fillRect(x - 50, y - 50, 100, 100);
      c.strokeStyle = '#dc2626';
      c.strokeRect(x - 50, y - 50, 100, 100);
      c.fillStyle = '#dc2626';
      c.font = 'bold 28px sans-serif';
      c.textAlign = 'center';
      c.fillText('✖ 崩塌', x, y + 10);
      c.restore();
      return;
    }
    const a = s * 0.866;
    const b = s * 0.5;

    c.fillStyle = 'rgba(59, 130, 246, 0.7)';
    c.beginPath();
    c.moveTo(x, y); c.lineTo(x + a, y - b); c.lineTo(x, y - 2*b); c.lineTo(x - a, y - b);
    c.closePath(); c.fill(); c.stroke();

    c.fillStyle = 'rgba(16, 185, 129, 0.7)';
    c.beginPath();
    c.moveTo(x, y); c.lineTo(x + a, y - b); c.lineTo(x + a, y + s - b); c.lineTo(x, y + s);
    c.closePath(); c.fill(); c.stroke();

    c.fillStyle = 'rgba(239, 68, 68, 0.7)';
    c.beginPath();
    c.moveTo(x, y); c.lineTo(x - a, y - b); c.lineTo(x - a, y + s - b); c.lineTo(x, y + s);
    c.closePath(); c.fill(); c.stroke();
    c.restore();
  }

  slF.oninput = update;
  resetBtn.onclick = () => { slF.value = 0; b1.click(); };
  update();
};



// ----------------------------------------------------------------------------
// Week 11: 無人機航拍與澳門世遺牌坊重建 (Drone Photogrammetry)
// ----------------------------------------------------------------------------
window.initExp_W11 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>飛行高度 H (米)</span><span id="vAlt" class="control-val">50</span></div>
      <input type="range" id="slAlt" class="control-slider" min="20" max="100" step="5" value="50">
    </div>
    <div class="control-group">
      <div class="control-label"><span>相機鏡頭視角 FOV</span><span id="vFov" class="control-val">60°</span></div>
      <div class="control-btn-group">
        <button class="btn-toggle active" id="bFov60">60° 廣角</button>
        <button class="btn-toggle" id="bFov84">84° 超廣角</button>
      </div>
    </div>
  `;

  let H = 50, fov = 60;
  const slH = document.getElementById('slAlt');
  const b1 = document.getElementById('bFov60'), b2 = document.getElementById('bFov84');

  b1.onclick = () => { fov = 60; b1.classList.add('active'); b2.classList.remove('active'); document.getElementById('vFov').textContent = '60°'; update(); };
  b2.onclick = () => { fov = 84; b2.classList.add('active'); b1.classList.remove('active'); document.getElementById('vFov').textContent = '84°'; update(); };

  function update() {
    H = parseInt(slH.value);
    document.getElementById('vAlt').textContent = H;

    // Ground coverage width = 2 * H * tan(fov/2)
    const rad = (fov / 2) * (Math.PI / 180);
    const groundW = (2 * H * Math.tan(rad)).toFixed(1);
    const scale = (H / 25.5).toFixed(1); // St Paul's is 25.5m high

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Ground line
    ctx.fillStyle = '#64748b';
    ctx.fillRect(40, 320, 620, 10);

    // St Paul's Ruins Facade (h = 25.5m)
    const facadeH = 25.5 * 3; // scaled
    ctx.fillStyle = '#94a3b8';
    ctx.fillRect(310, 320 - facadeH, 60, facadeH);
    ctx.strokeStyle = '#334155';
    ctx.strokeRect(310, 320 - facadeH, 60, facadeH);

    // Triangle pediment
    ctx.beginPath();
    ctx.moveTo(310, 320 - facadeH); ctx.lineTo(340, 320 - facadeH - 30); ctx.lineTo(370, 320 - facadeH);
    ctx.closePath(); ctx.fill(); ctx.stroke();

    ctx.fillStyle = '#0f172a';
    ctx.font = '11px sans-serif';
    ctx.fillText('大三巴 (25.5m)', 305, 345);

    // Drone position
    const droneY = 320 - H * 2.5;
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(325, droneY - 8, 30, 16);
    // Propellers
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(305, droneY - 10, 20, 4); ctx.fillRect(355, droneY - 10, 20, 4);

    // Projection cone
    const halfSpan = (groundW / 2) * 2.5;
    ctx.fillStyle = 'rgba(250, 204, 21, 0.25)';
    ctx.beginPath();
    ctx.moveTo(340, droneY);
    ctx.lineTo(340 - halfSpan, 320);
    ctx.lineTo(340 + halfSpan, 320);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = '#eab308';
    ctx.setLineDash([4, 4]);
    ctx.stroke();
    ctx.setLineDash([]);

    // HUD Text
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`無人機航拍幾何測繪 (飛行高度 H = ${H}m, 視場角 FOV = ${fov}°):`, 40, 40);

    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#15803d';
    ctx.fillText(`✔ 地面單張照片覆蓋跨度: 2 × ${H} × tan(${fov/2}°) = ${groundW} 米`, 40, 70);
    ctx.fillStyle = '#2563eb';
    ctx.fillText(`✔ 相似三角形測量比例尺: 牌坊高 25.5m 佔照片畫幅約 ${(25.5 / (groundW * 0.75) * 100).toFixed(1)}%`, 40, 95);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">航拍高度:</span><span class="readout-val">${H} 米</span></div>
      <div class="readout-item"><span class="readout-lbl">地面視場直徑:</span><span class="readout-val highlight">${groundW} 米</span></div>
      <div class="readout-item"><span class="readout-lbl">牌坊畫幅佔比:</span><span class="readout-val success">${(25.5 / (groundW * 0.75) * 100).toFixed(1)}%</span></div>
      <div class="readout-item"><span class="readout-lbl">3D建模質量:</span><span class="readout-val">${H<=50?'超高分辨率':'大範圍全景'}</span></div>
    `;

    currentRecordGetter = () => [
      `高度 ${H}m`, `${H} 米`, `${fov}°`, `${groundW} 米`, '25.5 米', `${(25.5 / (groundW * 0.75) * 100).toFixed(1)}%`
    ];
  }

  slH.oninput = update;
  resetBtn.onclick = () => { slH.value = 50; b1.click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 12: 國際物流『材積重』收費演算法 (Volumetric Weight vs Scale)
// ----------------------------------------------------------------------------
window.initExp_W12 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>包裹長 L (cm)</span><span id="vL" class="control-val">60</span></div>
      <input type="range" id="slL" class="control-slider" min="20" max="100" step="5" value="60">
    </div>
    <div class="control-group">
      <div class="control-label"><span>包裹寬 W (cm)</span><span id="vW" class="control-val">50</span></div>
      <input type="range" id="slW" class="control-slider" min="20" max="80" step="5" value="50">
    </div>
    <div class="control-group">
      <div class="control-label"><span>包裹高 H (cm)</span><span id="vH" class="control-val">40</span></div>
      <input type="range" id="slH" class="control-slider" min="10" max="80" step="5" value="40">
    </div>
    <div class="control-group">
      <div class="control-label"><span>實際稱重 (kg)</span><span id="vActW" class="control-val">8</span></div>
      <input type="range" id="slActW" class="control-slider" min="1" max="40" step="1" value="8">
    </div>
  `;

  const slL = document.getElementById('slL'), slW = document.getElementById('slW'), slH = document.getElementById('slH'), slA = document.getElementById('slActW');

  function update() {
    const L = parseInt(slL.value), W = parseInt(slW.value), H = parseInt(slH.value);
    const actW = parseFloat(slA.value);

    document.getElementById('vL').textContent = L;
    document.getElementById('vW').textContent = W;
    document.getElementById('vH').textContent = H;
    document.getElementById('vActW').textContent = actW;

    const vol = L * W * H; // cm3
    const volWeight = (vol / 6000).toFixed(2); // kg
    const billWeight = Math.max(actW, parseFloat(volWeight));
    const isVol = parseFloat(volWeight) > actW;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Weighing Scale
    ctx.fillStyle = '#475569';
    ctx.fillRect(80, 290, 180, 30);
    ctx.fillStyle = '#94a3b8';
    ctx.fillRect(100, 270, 140, 20);

    // Box on scale
    const boxW = Math.min(130, L * 1.3);
    const boxH = Math.min(100, H * 1.3);
    ctx.fillStyle = '#d97706';
    ctx.fillRect(170 - boxW/2, 270 - boxH, boxW, boxH);
    ctx.strokeStyle = '#78350f';
    ctx.lineWidth = 2;
    ctx.strokeRect(170 - boxW/2, 270 - boxH, boxW, boxH);

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 13px sans-serif';
    ctx.fillText(`${L}×${W}×${H} cm`, 170 - 45, 270 - boxH/2);

    // Formula & Economics Card on Right
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(320, 60, 330, 260);
    ctx.strokeStyle = isVol ? '#f59e0b' : '#3b82f6';
    ctx.lineWidth = 3;
    ctx.strokeRect(320, 60, 330, 260);

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText('國際物流材積重演算法比較', 340, 95);

    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#334155';
    ctx.fillText(`物理體積: ${vol.toLocaleString()} cm³`, 340, 135);
    ctx.fillText(`材積重量: ${vol} ÷ 6000 = ${volWeight} kg`, 340, 170);
    ctx.fillText(`實際稱重: ${actW} kg`, 340, 205);

    ctx.fillRect(340, 220, 290, 2);

    ctx.font = 'bold 16px sans-serif';
    ctx.fillStyle = isVol ? '#d97706' : '#2563eb';
    ctx.fillText(`最終計費重量: ${billWeight} kg`, 340, 255);

    ctx.font = 'bold 13px sans-serif';
    ctx.fillText(isVol ? '⚠️ 輕泡貨物：材積重超出實重，按材積計費' : '✔ 重貨物：密度較高，按實際稱重計費', 340, 290);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">體積:</span><span class="readout-val">${(vol/1000).toFixed(1)} L</span></div>
      <div class="readout-item"><span class="readout-lbl">材積重:</span><span class="readout-val highlight">${volWeight} kg</span></div>
      <div class="readout-item"><span class="readout-lbl">實際重量:</span><span class="readout-val">${actW} kg</span></div>
      <div class="readout-item"><span class="readout-lbl">計費判定:</span><span class="readout-val ${isVol?'danger':'success'}">${isVol?'按體積收費':'按實重收費'}</span></div>
    `;

    currentRecordGetter = () => [
      `${L}×${W}×${H} cm`, `${vol.toLocaleString()} cm³`, `${actW} kg`, `${volWeight} kg`, `${billWeight} kg`, isVol ? '體積泡貨' : '重貨'
    ];
  }

  slL.oninput = update; slW.oninput = update; slH.oninput = update; slA.oninput = update;
  resetBtn.onclick = () => { slL.value = 60; slW.value = 50; slH.value = 40; slA.value = 8; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 13: 阿基米德王冠之謎與沉降測量 (Displacement Method)
// ----------------------------------------------------------------------------
window.initExp_W13 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>王冠質量 m (g)</span><span id="vMass" class="control-val">1000</span></div>
      <input type="range" id="slMass" class="control-slider" min="500" max="1500" step="50" value="1000">
    </div>
    <div class="control-group">
      <div class="control-label"><span>摻銀比例</span><span id="vSilver" class="control-val">30% 摻銀</span></div>
      <input type="range" id="slSilver" class="control-slider" min="0" max="60" step="10" value="30">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="btnSubmerge">沉降測量中</button>
    </div>
  `;

  const slM = document.getElementById('slMass'), slS = document.getElementById('slSilver');

  function update() {
    const m = parseInt(slM.value);
    const sPercent = parseInt(slS.value);
    document.getElementById('vMass').textContent = m;
    document.getElementById('vSilver').textContent = `${sPercent}% 摻銀`;

    // Density: Gold = 19.3, Silver = 10.5
    const goldMass = m * (1 - sPercent / 100);
    const silverMass = m * (sPercent / 100);
    const volGold = goldMass / 19.3;
    const volSilver = silverMass / 10.5;
    const totalVol = (volGold + volSilver).toFixed(1);
    const avgDensity = (m / totalVol).toFixed(2);
    const isPure = (sPercent === 0);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Graduated Cylinder
    const cx = 180, cy = 340, cw = 110, ch = 240;
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 3;
    ctx.strokeRect(cx, cy - ch, cw, ch);

    // Water level
    const baseH = 120;
    const riseH = Math.min(90, parseFloat(totalVol) * 0.9);
    ctx.fillStyle = '#bae6fd';
    ctx.fillRect(cx + 2, cy - baseH - riseH, cw - 4, baseH + riseH);

    // Suspended Crown in water
    ctx.fillStyle = isPure ? '#eab308' : '#ca8a04';
    ctx.beginPath();
    ctx.arc(cx + cw/2, cy - 60, 32, 0, Math.PI*2);
    ctx.fill();
    ctx.strokeStyle = '#713f12';
    ctx.stroke();

    // Thread
    ctx.strokeStyle = '#94a3b8';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(cx + cw/2, cy - 92); ctx.lineTo(cx + cw/2, cy - ch - 20); ctx.stroke();

    // Floating Delta h line
    ctx.strokeStyle = '#dc2626';
    ctx.setLineDash([4, 2]);
    ctx.beginPath();
    ctx.moveTo(cx - 20, cy - baseH); ctx.lineTo(cx + cw + 20, cy - baseH);
    ctx.moveTo(cx - 20, cy - baseH - riseH); ctx.lineTo(cx + cw + 20, cy - baseH - riseH);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = '#dc2626';
    ctx.font = 'bold 12px sans-serif';
    ctx.fillText(`ΔV = ${totalVol} mL`, cx + cw + 28, cy - baseH - riseH/2 + 4);

    // Physics Results Card on Right
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(340, 60, 310, 260);
    ctx.strokeStyle = isPure ? '#16a34a' : '#ef4444';
    ctx.lineWidth = 3;
    ctx.strokeRect(340, 60, 310, 260);

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText('阿基米德王冠排水密度鑒定', 360, 95);

    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#334155';
    ctx.fillText(`排開水體積 ΔV = ${totalVol} cm³`, 360, 135);
    ctx.fillText(`王冠密度 ρ = ${m}g ÷ ${totalVol}cm³ = ${avgDensity} g/cm³`, 360, 170);
    ctx.fillText('純金標準密度: 19.3 g/cm³', 360, 205);
    ctx.fillText('純銀標準密度: 10.5 g/cm³', 360, 235);

    ctx.font = 'bold 15px sans-serif';
    ctx.fillStyle = isPure ? '#15803d' : '#dc2626';
    ctx.fillText(isPure ? '✔ 鑒定結果：純金真品！密度完全相符' : `✘ 鑒定結果：摻銀贗品！密度偏低 ${(19.3 - avgDensity).toFixed(2)} g/cm³`, 360, 285);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">排水體積:</span><span class="readout-val">${totalVol} mL</span></div>
      <div class="readout-item"><span class="readout-lbl">測得密度:</span><span class="readout-val highlight">${avgDensity} g/cm³</span></div>
      <div class="readout-item"><span class="readout-lbl">純金基準:</span><span class="readout-val">19.3 g/cm³</span></div>
      <div class="readout-item"><span class="readout-lbl">科學鑒定:</span><span class="readout-val ${isPure?'success':'danger'}">${isPure?'純金':'摻假'}</span></div>
    `;

    currentRecordGetter = () => [
      `王冠 ${m}g`, `${m} 克`, `${totalVol} cm³`, `${avgDensity} g/cm³`, '19.3 g/cm³', isPure ? '純金正品' : '摻銀造假'
    ];
  }

  slM.oninput = update; slS.oninput = update;
  resetBtn.onclick = () => { slM.value = 1000; slS.value = 30; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 14: 澳門水塘蓄水與城市暴雨排澇 (Reservoir Inflow & Drainage)
// ----------------------------------------------------------------------------
window.initExp_W14 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>暴雨進水流量 Qin (m³/s)</span><span id="vQin" class="control-val">60</span></div>
      <input type="range" id="slQin" class="control-slider" min="0" max="100" step="5" value="60">
    </div>
    <div class="control-group">
      <div class="control-label"><span>泵站抽排流量 Qout (m³/s)</span><span id="vQout" class="control-val">40</span></div>
      <input type="range" id="slQout" class="control-slider" min="0" max="80" step="5" value="40">
    </div>
    <div class="control-group">
      <div class="control-label"><span>持續時間 t (小時)</span><span id="vTime" class="control-val">2.0</span></div>
      <input type="range" id="slTime" class="control-slider" min="0.5" max="5.0" step="0.5" value="2.0">
    </div>
  `;

  const slIn = document.getElementById('slQin'), slOut = document.getElementById('slQout'), slT = document.getElementById('slTime');

  function update() {
    const qIn = parseInt(slIn.value);
    const qOut = parseInt(slOut.value);
    const t = parseFloat(slT.value);

    document.getElementById('vQin').textContent = qIn;
    document.getElementById('vQout').textContent = qOut;
    document.getElementById('vTime').textContent = t.toFixed(1);

    const netRate = qIn - qOut; // m3/s
    const netVol = (netRate * t * 3600).toFixed(0); // m3
    const baseStorage = 300000; // m3
    const curStorage = Math.max(0, baseStorage + parseInt(netVol));
    const isFlood = (curStorage > 500000);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Cross-section of Reservoir
    ctx.fillStyle = '#64748b';
    ctx.fillRect(80, 200, 30, 140); // left wall
    ctx.fillRect(490, 200, 30, 140); // right sea dike

    // Water body
    const maxStorageH = 120;
    const waterH = Math.min(135, (curStorage / 600000) * maxStorageH);
    ctx.fillStyle = isFlood ? '#ef4444' : '#38bdf8';
    ctx.fillRect(110, 340 - waterH, 380, waterH);

    // Flood danger line
    ctx.strokeStyle = '#dc2626';
    ctx.lineWidth = 2;
    ctx.setLineDash([6, 3]);
    ctx.beginPath(); ctx.moveTo(90, 340 - 100); ctx.lineTo(510, 340 - 100); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#dc2626';
    ctx.font = 'bold 11px sans-serif';
    ctx.fillText('防汛警戒水位線 (50 萬 m³)', 350, 340 - 106);

    // Inflow arrow
    ctx.fillStyle = '#2563eb';
    ctx.font = 'bold 14px sans-serif';
    ctx.fillText(`⛈️ 暴雨流入: ${qIn} m³/s`, 120, 150);

    // Outflow arrow
    ctx.fillStyle = '#059669';
    ctx.fillText(`🌊 泵站外排: ${qOut} m³/s`, 420, 150);

    // Bottom summary
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(80, 20, 520, 80);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(80, 20, 520, 80);

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`淨積水速率 = ${qIn} - ${qOut} = ${netRate} m³/s | ${t} 小時水量變化 = ${(netVol/10000).toFixed(1)} 萬立方米`, 100, 50);

    ctx.font = 'bold 14px sans-serif';
    ctx.fillStyle = isFlood ? '#dc2626' : '#16a34a';
    ctx.fillText(isFlood ? '⚠️ 暴雨超警戒！蓄水量達上限，存在市區海水倒灌風險，需啟動應急排澇' : '✔ 防汛安全受控：水塘具備足夠調蓄庫容', 100, 80);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">入水:</span><span class="readout-val">${qIn} m³/s</span></div>
      <div class="readout-item"><span class="readout-lbl">出水:</span><span class="readout-val">${qOut} m³/s</span></div>
      <div class="readout-item"><span class="readout-lbl">總蓄水量:</span><span class="readout-val highlight">${(curStorage/10000).toFixed(1)} 萬 m³</span></div>
      <div class="readout-item"><span class="readout-lbl">汛情評估:</span><span class="readout-val ${isFlood?'danger':'success'}">${isFlood?'超警戒線':'安全受控'}</span></div>
    `;

    currentRecordGetter = () => [
      `暴雨測試 ${t}h`, `${qIn} m³/s`, `${qOut} m³/s`, `${netRate} m³/s`, `${t} 小時`, `${(curStorage/10000).toFixed(1)} 萬 m³`, isFlood ? '超警戒' : '安全'
    ];
  }

  slIn.oninput = update; slOut.oninput = update; slT.oninput = update;
  resetBtn.onclick = () => { slIn.value = 60; slOut.value = 40; slT.value = 2.0; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 15: 全球氣候暖化與坐標軸截斷陷阱 (Manipulated Y-Axis Chart)
// ----------------------------------------------------------------------------
window.initExp_W15 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>數值增長幅度</span><span id="vGrowth" class="control-val">5%</span></div>
      <input type="range" id="slGrowth" class="control-slider" min="1" max="15" step="1" value="5">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bTrunc">截斷 Y 軸 (從 90 起始)</button>
      <button class="btn-toggle" id="bHonest">誠實 Y 軸 (從 0 起始)</button>
    </div>
  `;

  let growth = 5, isTruncated = true;
  const slG = document.getElementById('slGrowth');
  const bTr = document.getElementById('bTrunc'), bHo = document.getElementById('bHonest');

  bTr.onclick = () => { isTruncated = true; bTr.classList.add('active'); bHo.classList.remove('active'); update(); };
  bHo.onclick = () => { isTruncated = false; bHo.classList.add('active'); bTr.classList.remove('active'); update(); };

  function update() {
    growth = parseInt(slG.value);
    document.getElementById('vGrowth').textContent = `${growth}%`;

    const valA = 100;
    const valB = 100 * (1 + growth / 100);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`媒體數據圖表審查：坐標軸截斷對公眾認知的誤導 (${isTruncated ? '⚠️ 截斷失真模式' : '✔ 誠實客觀模式'})`, 40, 40);

    const chartX = 140, chartY = 310, chartH = 220;

    // Y Axis
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(chartX, chartY); ctx.lineTo(chartX, chartY - chartH); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(chartX, chartY); ctx.lineTo(chartX + 420, chartY); ctx.stroke();

    let yMin = isTruncated ? 90 : 0;
    let yMax = isTruncated ? 115 : 120;

    // Axis Labels
    ctx.fillStyle = '#475569';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(`${yMin}`, chartX - 10, chartY + 5);
    ctx.fillText(`${yMax}`, chartX - 10, chartY - chartH + 10);
    ctx.fillText(`${(yMin+yMax)/2}`, chartX - 10, chartY - chartH/2 + 5);

    // Broken line marker if truncated
    if (isTruncated) {
      ctx.strokeStyle = '#dc2626';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(chartX - 6, chartY - 20); ctx.lineTo(chartX + 6, chartY - 26);
      ctx.moveTo(chartX - 6, chartY - 14); ctx.lineTo(chartX + 6, chartY - 20);
      ctx.stroke();
    }

    // Bar 1 (2020年)
    const hA = ((valA - yMin) / (yMax - yMin)) * chartH;
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(chartX + 70, chartY - hA, 70, hA);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('100.0', chartX + 105, chartY - hA + 24);

    // Bar 2 (2024年)
    const hB = ((valB - yMin) / (yMax - yMin)) * chartH;
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(chartX + 220, chartY - hB, 70, hB);
    ctx.fillStyle = '#ffffff';
    ctx.fillText(valB.toFixed(1), chartX + 255, chartY - hB + 24);

    ctx.fillStyle = '#0f172a';
    ctx.font = '14px sans-serif';
    ctx.fillText('2020 年基線', chartX + 105, chartY + 25);
    ctx.fillText('2024 年數值', chartX + 255, chartY + 25);

    // Visual amplification ratio
    const visualGrowth = ((hB - hA) / hA) * 100;
    ctx.textAlign = 'left';
    ctx.fillStyle = isTruncated ? '#dc2626' : '#15803d';
    ctx.font = 'bold 14px sans-serif';
    if (isTruncated) {
      ctx.fillText(`視覺誇大率: 柱高看似暴漲 ${visualGrowth.toFixed(0)}%！(真實僅增長 ${growth}%)`, 380, 120);
      ctx.fillStyle = '#64748b';
      ctx.font = '12px sans-serif';
      ctx.fillText(`失真倍數: 放大約 ${(visualGrowth / growth).toFixed(1)} 倍`, 380, 145);
    } else {
      ctx.fillText(`誠實對比：柱高增長比例與實際數據 ${growth}% 完全一致。`, 380, 120);
    }
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">實際增長:</span><span class="readout-val">${growth}%</span></div>
      <div class="readout-item"><span class="readout-lbl">Y軸起始點:</span><span class="readout-val highlight">${yMin}</span></div>
      <div class="readout-item"><span class="readout-lbl">視覺柱高增幅:</span><span class="readout-val ${isTruncated?'danger':'success'}">${visualGrowth.toFixed(1)}%</span></div>
      <div class="readout-item"><span class="readout-lbl">媒體審查結論:</span><span class="readout-val">${isTruncated?'存在視覺誤導':'客觀真實'}</span></div>
    `;

    currentRecordGetter = () => [
      `${growth}% 增長`, `${yMin}`, `${valA}`, `${valB.toFixed(1)}`, `${visualGrowth.toFixed(1)}%`, isTruncated ? '嚴重放大' : '客觀'
    ];
  }

  slG.oninput = update;
  resetBtn.onclick = () => { slG.value = 5; bTr.click(); };
  update();
};



// ----------------------------------------------------------------------------
// Week 16: 工廠質檢合格率與抽樣公正性 (Sampling Size & Defect Rate)
// ----------------------------------------------------------------------------
window.initExp_W16 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>抽檢樣本數 n (件)</span><span id="vSamp" class="control-val">20</span></div>
      <input type="range" id="slSamp" class="control-slider" min="5" max="100" step="5" value="20">
    </div>
    <div class="control-group">
      <div class="control-label"><span>工廠真實次品率</span><span id="vTrueDef" class="control-val">5%</span></div>
      <input type="range" id="slTrueDef" class="control-slider" min="1" max="10" step="1" value="5">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="btnResample">🎲 重新隨機抽檢</button>
    </div>
  `;

  let n = 20, trueDef = 5;
  const slN = document.getElementById('slSamp'), slD = document.getElementById('slTrueDef');
  const btnR = document.getElementById('btnResample');

  let sampleResults = [];

  function doSample() {
    sampleResults = [];
    let defectCount = 0;
    for (let i = 0; i < n; i++) {
      const isDef = Math.random() * 100 < trueDef;
      if (isDef) defectCount++;
      sampleResults.push(isDef);
    }
    update(defectCount);
  }

  btnR.onclick = doSample;

  function update(defects) {
    n = parseInt(slN.value);
    trueDef = parseInt(slD.value);
    document.getElementById('vSamp').textContent = n;
    document.getElementById('vTrueDef').textContent = `${trueDef}%`;

    if (defects === undefined) {
      defects = sampleResults.filter(x => x).length;
    }

    const sampleDefRate = ((defects / n) * 100).toFixed(1);
    const samplePassRate = (100 - parseFloat(sampleDefRate)).toFixed(1);
    const errorMargin = Math.abs(parseFloat(sampleDefRate) - trueDef).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`大數定律隨機抽樣沙盒 (母體真實次品率: ${trueDef}%, 抽檢樣本容量: ${n} 件):`, 40, 40);

    // Grid of samples
    const gridCols = 15;
    const startX = 60, startY = 75;
    for (let i = 0; i < n; i++) {
      const gx = startX + (i % gridCols) * 36;
      const gy = startY + Math.floor(i / gridCols) * 36;
      const isDef = sampleResults[i];

      ctx.fillStyle = isDef ? '#ef4444' : '#10b981';
      ctx.fillRect(gx, gy, 28, 28);
      ctx.strokeStyle = '#0f172a';
      ctx.strokeRect(gx, gy, 28, 28);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(isDef ? '✕' : '✔', gx + 14, gy + 19);
    }

    // Comparison summary
    const sumY = 240;
    ctx.textAlign = 'left';
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(40, sumY, 620, 100);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(40, sumY, 620, 100);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`抽樣檢出次品: ${defects} 件 | 樣本次品率 = ${sampleDefRate}% (合格率 ${samplePassRate}%)`, 60, sumY + 30);

    ctx.font = '13px sans-serif';
    ctx.fillStyle = parseFloat(errorMargin) <= 2 ? '#15803d' : '#b45309';
    ctx.fillText(`與真實次品率偏差: ${errorMargin}% (${parseFloat(errorMargin)<=2?'估計準確穩定':'小樣本波動較大'})`, 60, sumY + 58);

    ctx.fillStyle = '#64748b';
    ctx.fillText('★ 統計啟示：樣本容量 n 越大，樣本頻率越向真實概率大數收斂，減少錯判與漏檢風險。', 60, sumY + 84);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">樣本數:</span><span class="readout-val">${n} 件</span></div>
      <div class="readout-item"><span class="readout-lbl">檢出次品:</span><span class="readout-val ${defects>0?'danger':'success'}">${defects} 件</span></div>
      <div class="readout-item"><span class="readout-lbl">樣本合格率:</span><span class="readout-val highlight">${samplePassRate}%</span></div>
      <div class="readout-item"><span class="readout-lbl">抽樣公正性:</span><span class="readout-val">${n>=50?'高信度':'易受波動干擾'}</span></div>
    `;

    currentRecordGetter = () => [
      `抽樣組 n=${n}`, `${n} 件`, `${trueDef}%`, `${defects} 件`, `${samplePassRate}%`, `${errorMargin}%`
    ];
  }

  slN.oninput = doSample; slD.oninput = doSample;
  resetBtn.onclick = () => { slN.value = 20; slD.value = 5; doSample(); };
  doSample();
};

// ----------------------------------------------------------------------------
// Week 17: 促銷折上折的算術審計 (Sequential Percentage Discounts)
// ----------------------------------------------------------------------------
window.initExp_W17 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>第一重折扣率 d1</span><span id="vD1" class="control-val">0.8 (八折)</span></div>
      <input type="range" id="slD1" class="control-slider" min="0.5" max="0.9" step="0.05" value="0.8">
    </div>
    <div class="control-group">
      <div class="control-label"><span>第二重折扣率 d2</span><span id="vD2" class="control-val">0.9 (九折)</span></div>
      <input type="range" id="slD2" class="control-slider" min="0.5" max="0.95" step="0.05" value="0.9">
    </div>
    <div class="control-group">
      <div class="control-label"><span>商品原價 P (元)</span><span id="vPrice17" class="control-val">500</span></div>
      <input type="range" id="slP17" class="control-slider" min="100" max="1000" step="50" value="500">
    </div>
  `;

  const s1 = document.getElementById('slD1'), s2 = document.getElementById('slD2'), sp = document.getElementById('slP17');

  function update() {
    const d1 = parseFloat(s1.value), d2 = parseFloat(s2.value), P = parseFloat(sp.value);
    document.getElementById('vD1').textContent = `${d1} (${Math.round(d1*10)}折)`;
    document.getElementById('vD2').textContent = `${d2} (${Math.round(d2*10)}折)`;
    document.getElementById('vPrice17').textContent = P;

    const priceAfter1 = P * d1;
    const finalPrice = priceAfter1 * d2;
    const effectiveDisc = (d1 * d2 * 10).toFixed(1);
    const illusionDisc = ((1 - (1 - d1 + 1 - d2)) * 10).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('連續百分率折扣連乘幾何面積遞減模型:', 40, 45);

    // Stepwise reduction bar
    const barX = 60, barY = 85, barW = 540, barH = 50;

    // 100% Base Bar
    ctx.fillStyle = '#e2e8f0';
    ctx.fillRect(barX, barY, barW, barH);
    ctx.strokeStyle = '#0f172a';
    ctx.strokeRect(barX, barY, barW, barH);

    // After 1st discount
    ctx.fillStyle = '#60a5fa';
    ctx.fillRect(barX, barY, barW * d1, barH);
    ctx.strokeStyle = '#1d4ed8';
    ctx.strokeRect(barX, barY, barW * d1, barH);

    // After 2nd discount
    ctx.fillStyle = '#34d399';
    ctx.fillRect(barX, barY, barW * d1 * d2, barH);
    ctx.strokeStyle = '#059669';
    ctx.strokeRect(barX, barY, barW * d1 * d2, barH);

    // Labels
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 13px sans-serif';
    ctx.fillText(`最終實付: $${finalPrice.toFixed(1)} (${(d1*d2*100).toFixed(0)}%)`, barX + 15, barY + 30);

    // Comparative Analysis
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(40, 175, 620, 150);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(40, 175, 620, 150);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText(`原價 $${P} ➔ 打 ${Math.round(d1*10)} 折 ($${priceAfter1.toFixed(1)}) ➔ 再打 ${Math.round(d2*10)} 折 ➔ 實付 $${finalPrice.toFixed(1)}`, 60, 210);

    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#15803d';
    ctx.fillText(`✔ 真正綜合折扣: ${d1} × ${d2} = ${(d1*d2).toFixed(2)} (相當於 ${effectiveDisc} 折，實質讓利 ${(100 - d1*d2*100).toFixed(1)}%)`, 60, 245);

    ctx.fillStyle = '#dc2626';
    ctx.fillText(`✘ 直覺加總錯誤：誤以為讓利 ${(1-d1)*100}% + ${(1-d2)*100}% = ${(1-d1+1-d2)*100}% (即 ${illusionDisc} 折)`, 60, 275);
    ctx.fillStyle = '#64748b';
    ctx.font = '12px sans-serif';
    ctx.fillText(`算術審計真相：第二重折扣的基數已經是折後價，而非原價，故百分率絕對不能直接相加！`, 60, 305);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">原價:</span><span class="readout-val">$${P}</span></div>
      <div class="readout-item"><span class="readout-lbl">實付金額:</span><span class="readout-val success">$${finalPrice.toFixed(1)}</span></div>
      <div class="readout-item"><span class="readout-lbl">等效折扣:</span><span class="readout-val highlight">${effectiveDisc} 折</span></div>
      <div class="readout-item"><span class="readout-lbl">實質讓利:</span><span class="readout-val">${(100 - d1*d2*100).toFixed(1)}%</span></div>
    `;

    currentRecordGetter = () => [
      `原價$${P}`, `${Math.round(d1*10)}折`, `${Math.round(d2*10)}折`, `$${priceAfter1.toFixed(1)}`, `$${finalPrice.toFixed(1)}`, `${effectiveDisc} 折`, `${(100 - d1*d2*100).toFixed(1)}%`
    ];
  }

  s1.oninput = update; s2.oninput = update; sp.oninput = update;
  resetBtn.onclick = () => { s1.value = 0.8; s2.value = 0.9; sp.value = 500; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 18: 複利滾存與通膨家庭理財 (Compound Growth & Inflation)
// ----------------------------------------------------------------------------
window.initExp_W18 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>本金 P (萬元)</span><span id="vPrin" class="control-val">10</span></div>
      <input type="range" id="slPrin" class="control-slider" min="5" max="50" step="5" value="10">
    </div>
    <div class="control-group">
      <div class="control-label"><span>年化收益率 r</span><span id="vRate" class="control-val">6%</span></div>
      <input type="range" id="slRate" class="control-slider" min="2" max="10" step="1" value="6">
    </div>
    <div class="control-group">
      <div class="control-label"><span>存期 t (年)</span><span id="vYears" class="control-val">12</span></div>
      <input type="range" id="slYears" class="control-slider" min="1" max="25" value="12">
    </div>
  `;

  const sP = document.getElementById('slPrin'), sR = document.getElementById('slRate'), sY = document.getElementById('slYears');

  function update() {
    const P = parseFloat(sP.value) * 10000;
    const r = parseFloat(sR.value) / 100;
    const t = parseInt(sY.value);

    document.getElementById('vPrin').textContent = sP.value;
    document.getElementById('vRate').textContent = `${sR.value}%`;
    document.getElementById('vYears').textContent = t;

    const compoundTotal = P * Math.pow(1 + r, t);
    const simpleTotal = P * (1 + r * t);
    const doubleYears = (72 / (r * 100)).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`複利指數增長曲線 vs 單利線性增長 (本金 $${(P/10000).toFixed(0)}萬, 年化 ${sR.value}%):`, 40, 40);

    // Multi-curve chart
    const ox = 70, oy = 280, gw = 540, gh = 200;
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox + gw, oy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox, oy - gh); ctx.stroke();

    // Max scale
    const maxVal = P * Math.pow(1 + r, 25);

    // Plot simple
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let yr = 0; yr <= 25; yr++) {
      const px = ox + (yr / 25) * gw;
      const py = oy - ((P * (1 + r * yr)) / maxVal) * gh;
      if (yr === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();

    // Plot compound
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 3;
    ctx.beginPath();
    for (let yr = 0; yr <= 25; yr++) {
      const px = ox + (yr / 25) * gw;
      const py = oy - ((P * Math.pow(1 + r, yr)) / maxVal) * gh;
      if (yr === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();

    // Current point dot
    const curX = ox + (t / 25) * gw;
    const curY = oy - (compoundTotal / maxVal) * gh;
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(curX, curY, 6, 0, Math.PI*2); ctx.fill();

    // Summary Banner
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`第 ${t} 年複利總資產: $${(compoundTotal/10000).toFixed(2)} 萬元 (純收益 $${((compoundTotal - P)/10000).toFixed(2)} 萬)`, 100, 315);
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#059669';
    ctx.fillText(`72 法則翻倍估算: 72 ÷ ${sR.value} = 約 ${doubleYears} 年本金翻倍！`, 100, 340);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">本金:</span><span class="readout-val">$${(P/10000).toFixed(0)} 萬</span></div>
      <div class="readout-item"><span class="readout-lbl">複利總值:</span><span class="readout-val success">$${(compoundTotal/10000).toFixed(2)} 萬</span></div>
      <div class="readout-item"><span class="readout-lbl">單利對比:</span><span class="readout-val">$${(simpleTotal/10000).toFixed(2)} 萬</span></div>
      <div class="readout-item"><span class="readout-lbl">翻倍年限:</span><span class="readout-val highlight">~${doubleYears} 年</span></div>
    `;

    currentRecordGetter = () => [
      `存期 ${t}年`, `$${(P/10000).toFixed(0)} 萬`, `${sR.value}%`, `${t} 年`, `$${(compoundTotal/10000).toFixed(2)} 萬`, `$${(simpleTotal/10000).toFixed(2)} 萬`
    ];
  }

  sP.oninput = update; sR.oninput = update; sY.oninput = update;
  resetBtn.onclick = () => { sP.value = 10; sR.value = 6; sY.value = 12; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 19: 車輪為什麼必須是圓的？ (Rolling Wheel Axle Path)
// ----------------------------------------------------------------------------
window.initExp_W19 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>車輪前進轉動角度</span><span id="vRot" class="control-val">0°</span></div>
      <input type="range" id="slRot" class="control-slider" min="0" max="360" value="0">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bShapeCirc">圓形車輪</button>
      <button class="btn-toggle" id="bShapeSquare">正方形車輪</button>
      <button class="btn-toggle" id="bShapeTri">正三角形車輪</button>
    </div>
  `;

  let rot = 0, shape = 'circ';
  const slR = document.getElementById('slRot');
  const bc = document.getElementById('bShapeCirc'), bs = document.getElementById('bShapeSquare'), bt = document.getElementById('bShapeTri');

  function setShape(sh, btn) {
    shape = sh;
    [bc, bs, bt].forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    update();
  }
  bc.onclick = () => setShape('circ', bc);
  bs.onclick = () => setShape('square', bs);
  bt.onclick = () => setShape('tri', bt);

  function update() {
    rot = parseInt(slR.value);
    document.getElementById('vRot').textContent = `${rot}°`;

    const rad = (rot * Math.PI) / 180;
    const R = 45;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Roadway
    ctx.fillStyle = '#334155';
    ctx.fillRect(40, 260, 620, 40);

    const ox = 120 + (rot / 360) * 440;
    let axleY = 260 - R;

    let deltaH = 0;
    if (shape === 'square') {
      const angleInQuad = (rot % 90) * (Math.PI / 180);
      const halfSide = R / Math.SQRT2;
      axleY = 260 - halfSide * (Math.cos(angleInQuad - Math.PI/4));
      deltaH = (halfSide * Math.SQRT2 - halfSide).toFixed(1);
    } else if (shape === 'tri') {
      deltaH = (R * 0.5).toFixed(1);
    }

    // Axle Path (Red line)
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(80, shape==='circ' ? 260 - R : 260 - R - 15);
    ctx.lineTo(ox, axleY);
    ctx.stroke();

    // Wheel
    ctx.save();
    ctx.translate(ox, axleY);
    ctx.rotate(rad);

    if (shape === 'circ') {
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath(); ctx.arc(0, 0, R, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = '#1e3a8a'; ctx.lineWidth = 3; ctx.stroke();
      // Spokes
      ctx.strokeStyle = '#ffffff';
      ctx.beginPath(); ctx.moveTo(-R, 0); ctx.lineTo(R, 0); ctx.moveTo(0, -R); ctx.lineTo(0, R); ctx.stroke();
    } else if (shape === 'square') {
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(-R*0.7, -R*0.7, R*1.4, R*1.4);
      ctx.strokeStyle = '#b45309'; ctx.lineWidth = 3;
      ctx.strokeRect(-R*0.7, -R*0.7, R*1.4, R*1.4);
    } else {
      ctx.fillStyle = '#ec4899';
      ctx.beginPath();
      ctx.moveTo(0, -R); ctx.lineTo(R*0.866, R*0.5); ctx.lineTo(-R*0.866, R*0.5);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = '#9d174d'; ctx.lineWidth = 3; ctx.stroke();
    }
    ctx.restore();

    // Axle center dot
    ctx.fillStyle = '#dc2626';
    ctx.beginPath(); ctx.arc(ox, axleY, 5, 0, Math.PI*2); ctx.fill();

    // HUD Text
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('車輪滾動中軸心運動軌跡與平穩度對比:', 40, 45);

    ctx.font = '14px sans-serif';
    ctx.fillStyle = shape === 'circ' ? '#15803d' : '#dc2626';
    if (shape === 'circ') {
      ctx.fillText('✔ 圓形車輪：圓上任意點到圓心距離恆等於半徑 r，車軸軌跡為絕對水平直線，零震動平穩行駛！', 40, 75);
    } else {
      ctx.fillText(`✘ 非圓形車輪：軸心上下劇烈顛簸震盪 (垂直起伏 Δy ≈ ${deltaH} cm)，車輛會劇烈跳動損毀！`, 40, 75);
    }
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">車輪構型:</span><span class="readout-val">${shape==='circ'?'圓形':(shape==='square'?'正方形':'正三角形')}</span></div>
      <div class="readout-item"><span class="readout-lbl">轉動角:</span><span class="readout-val">${rot}°</span></div>
      <div class="readout-item"><span class="readout-lbl">車軸高度:</span><span class="readout-val highlight">${(260 - axleY).toFixed(1)} px</span></div>
      <div class="readout-item"><span class="readout-lbl">平穩舒適度:</span><span class="readout-val ${shape==='circ'?'success':'danger'}">${shape==='circ'?'極致平穩':'劇烈顛簸'}</span></div>
    `;

    currentRecordGetter = () => [
      `${shape==='circ'?'圓形車輪':(shape==='square'?'方形車輪':'三角形車輪')}`, `${rot}°`, `${(260 - axleY).toFixed(1)} px`, shape==='circ'?'0 cm':'劇烈起伏', shape==='circ'?'平直水平線':'波浪跳動', shape==='circ'?'舒適' : '無法乘坐'
    ];
  }

  slR.oninput = update;
  resetBtn.onclick = () => { slR.value = 0; bc.click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 20: 祖沖之割圓術與極限逼近 (Inscribed Polygon Approximation to Pi)
// ----------------------------------------------------------------------------
window.initExp_W20 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>割圓內接正多邊形邊數 n</span><span id="vEdges" class="control-val">6 邊形</span></div>
      <input type="range" id="slEdges" class="control-slider" min="1" max="6" value="1">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bStep1">n = 6</button>
      <button class="btn-toggle" id="bStep2">n = 12</button>
      <button class="btn-toggle" id="bStep3">n = 24</button>
      <button class="btn-toggle" id="bStep4">n = 48</button>
      <button class="btn-toggle" id="bStep5">n = 96</button>
    </div>
  `;

  const edgesMap = [6, 12, 24, 48, 96, 192];
  let curIndex = 0;
  const slE = document.getElementById('slEdges');
  const bList = [document.getElementById('bStep1'), document.getElementById('bStep2'), document.getElementById('bStep3'), document.getElementById('bStep4'), document.getElementById('bStep5')];

  bList.forEach((btn, idx) => {
    btn.onclick = () => {
      curIndex = idx;
      slE.value = idx + 1;
      bList.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      update();
    };
  });

  function update() {
    curIndex = parseInt(slE.value) - 1;
    const n = edgesMap[curIndex];
    document.getElementById('vEdges').textContent = `${n} 邊形`;

    // Math calculation for pi approximation
    const approxPi = (n * Math.sin(Math.PI / n)).toFixed(5);
    const error = Math.abs(parseFloat(approxPi) - Math.PI).toFixed(5);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    // Draw circle
    const ox = 220, oy = 210, R = 130;
    ctx.strokeStyle = '#cbd5e1';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(ox, oy, R, 0, Math.PI*2); ctx.stroke();

    // Draw Inscribed Polygon
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 3;
    ctx.fillStyle = 'rgba(59, 130, 246, 0.15)';
    ctx.beginPath();
    for (let i = 0; i < n; i++) {
      const theta = (i * 2 * Math.PI) / n;
      const px = ox + R * Math.cos(theta);
      const py = oy + R * Math.sin(theta);
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Algorithm & Pi Card on Right
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(400, 60, 260, 260);
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.strokeRect(400, 60, 260, 260);

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText('劉徽割圓術極限逼近', 420, 95);

    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#334155';
    ctx.fillText(`當前內接多邊形: 正 ${n} 邊形`, 420, 135);
    ctx.fillText(`推算圓周率: π ≈ ${approxPi}`, 420, 170);
    ctx.fillText(`真實圓周率: 3.14159...`, 420, 205);
    ctx.fillText(`逼近誤差: ${error}`, 420, 240);

    ctx.font = 'bold 13px sans-serif';
    ctx.fillStyle = '#15803d';
    ctx.fillText('「割之彌細，所失彌少」', 420, 285);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">內接邊數:</span><span class="readout-val">${n} 邊</span></div>
      <div class="readout-item"><span class="readout-lbl">逼近 π 值:</span><span class="readout-val highlight">${approxPi}</span></div>
      <div class="readout-item"><span class="readout-lbl">誤差:</span><span class="readout-val success">${error}</span></div>
      <div class="readout-item"><span class="readout-lbl">極限狀態:</span><span class="readout-val">${n>=96?'極高精確度':'初期逼近'}</span></div>
    `;

    currentRecordGetter = () => [
      `正 ${n} 邊形`, `${n} 邊`, `${(2*Math.sin(Math.PI/n)).toFixed(4)}`, `${(n*Math.sin(Math.PI/n)).toFixed(5)}`, `${approxPi}`, `${error}`
    ];
  }

  slE.oninput = update;
  resetBtn.onclick = () => { bList[0].click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 21: 澳門蓮花球場 400米跑道起跑差 (Staggered Track Lanes)
// ----------------------------------------------------------------------------
window.initExp_W21 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>跑道道寬 w (m)</span><span id="vLaneW" class="control-val">1.22</span></div>
      <input type="range" id="slLaneW" class="control-slider" min="1.0" max="1.25" step="0.01" value="1.22">
    </div>
    <div class="control-group">
      <div class="control-label"><span>觀察道次</span><span id="vLaneNo" class="control-val">第 2 道</span></div>
      <input type="range" id="slLaneNo" class="control-slider" min="2" max="8" value="2">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bRace400">400米 (一整圈)</button>
      <button class="btn-toggle" id="bRace200">200米 (半圈彎道)</button>
    </div>
  `;

  let w = 1.22, lane = 2, race = 400;
  const slW = document.getElementById('slLaneW'), slL = document.getElementById('slLaneNo');
  const b400 = document.getElementById('bRace400'), b200 = document.getElementById('bRace200');

  b400.onclick = () => { race = 400; b400.classList.add('active'); b200.classList.remove('active'); update(); };
  b200.onclick = () => { race = 200; b200.classList.add('active'); b400.classList.remove('active'); update(); };

  function update() {
    w = parseFloat(slW.value);
    lane = parseInt(slL.value);
    document.getElementById('vLaneW').textContent = w.toFixed(2);
    document.getElementById('vLaneNo').textContent = `第 ${lane} 道`;

    // 400m stagger = 2 * pi * (lane - 1) * w
    // 200m stagger = pi * (lane - 1) * w
    const factor = race === 400 ? 2 : 1;
    const stagger = (factor * Math.PI * (lane - 1) * w).toFixed(2);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`400米標準田徑場跑道起跑線前移測算 (道寬 w = ${w}m, ${race}米賽事):`, 40, 40);

    // Overhead Track drawing
    const cx = 350, cy = 200, rBase = 70, straightL = 120;
    const laneColors = ['#f87171', '#fb923c', '#fbbf24', '#a3e635', '#34d399', '#22d3ee', '#818cf8', '#c084fc'];

    for (let l = 8; l >= 1; l--) {
      const curR = rBase + (l - 1) * 8;
      ctx.strokeStyle = (l === lane) ? '#dc2626' : '#cbd5e1';
      ctx.lineWidth = (l === lane) ? 6 : 2;

      ctx.beginPath();
      // Left curve
      ctx.arc(cx - straightL/2, cy, curR, 0.5*Math.PI, 1.5*Math.PI);
      // Top straight
      ctx.lineTo(cx + straightL/2, cy - curR);
      // Right curve
      ctx.arc(cx + straightL/2, cy, curR, 1.5*Math.PI, 0.5*Math.PI);
      // Bottom straight
      ctx.lineTo(cx - straightL/2, cy + curR);
      ctx.stroke();
    }

    // Runner marker at start
    ctx.fillStyle = '#dc2626';
    ctx.beginPath(); ctx.arc(cx + straightL/2, cy + rBase + (lane - 1)*8, 6, 0, Math.PI*2); ctx.fill();

    // Annotation
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`第 ${lane} 道起跑前移補償: ${factor} × π × (${lane} - 1) × ${w} = ${stagger} 米`, 80, 310);
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#059669';
    ctx.fillText(`✔ 公平競技：外道彎道周長大於內道，起跑線前移 ${stagger}m 確保每位選手總跑程完全相同。`, 80, 335);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">道寬:</span><span class="readout-val">${w} m</span></div>
      <div class="readout-item"><span class="readout-lbl">道次:</span><span class="readout-val">第 ${lane} 道</span></div>
      <div class="readout-item"><span class="readout-lbl">前移補償距離:</span><span class="readout-val highlight">${stagger} 米</span></div>
      <div class="readout-item"><span class="readout-lbl">賽事類型:</span><span class="readout-val success">${race} 米</span></div>
    `;

    currentRecordGetter = () => [
      `第 ${lane} 道`, `${w} 米`, `${lane}`, `${race} 米`, `${factor}π(k-1)w`, `${stagger} 米`
    ];
  }

  slW.oninput = update; slL.oninput = update;
  resetBtn.onclick = () => { slW.value = 1.22; slL.value = 2; b400.click(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 22: 化圓為方：剪拼轉化 (Circle Unfolding to Rectangle)
// ----------------------------------------------------------------------------
window.initExp_W22 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>扇形等分數 n</span><span id="vSectors" class="control-val">16 等分</span></div>
      <input type="range" id="slSectors" class="control-slider" min="1" max="4" value="2">
    </div>
    <div class="control-group">
      <div class="control-label"><span>展開拼貼進度</span><span id="vUnfold" class="control-val">0%</span></div>
      <input type="range" id="slUnfold" class="control-slider" min="0" max="100" value="0">
    </div>
  `;

  const nList = [8, 16, 32, 64];
  const slS = document.getElementById('slSectors'), slU = document.getElementById('slUnfold');

  function update() {
    const n = nList[parseInt(slS.value) - 1];
    const p = parseInt(slU.value) / 100;
    document.getElementById('vSectors').textContent = `${n} 等分`;
    document.getElementById('vUnfold').textContent = `${parseInt(slU.value)}%`;

    const r = 80;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`圓面積剪拼轉化長方形微積分演繹 (${n} 等分, 展開進度 ${(p*100).toFixed(0)}%):`, 40, 40);

    if (p < 0.5) {
      // Draw Circle with alternating sectors
      const ox = 240, oy = 180;
      for (let i = 0; i < n; i++) {
        const a1 = (i * 2 * Math.PI) / n;
        const a2 = ((i + 1) * 2 * Math.PI) / n;
        ctx.fillStyle = (i % 2 === 0) ? '#3b82f6' : '#f59e0b';
        ctx.beginPath();
        ctx.moveTo(ox, oy);
        ctx.arc(ox, oy, r, a1, a2);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = '#ffffff';
        ctx.stroke();
      }
    } else {
      // Draw unfolded interleaved rectangle
      const rx = 120, ry = 140, rectW = Math.PI * r, rectH = r;
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(rx, ry, rectW, rectH / 2);
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(rx, ry + rectH / 2, rectW, rectH / 2);
      ctx.strokeStyle = '#0f172a';
      ctx.lineWidth = 2;
      ctx.strokeRect(rx, ry, rectW, rectH);

      // Dimension brackets
      ctx.fillStyle = '#0f172a';
      ctx.font = 'bold 14px sans-serif';
      ctx.fillText(`底邊長 = π × r ≈ ${(Math.PI * r).toFixed(1)} px`, rx + rectW/2 - 60, ry + rectH + 25);
      ctx.fillText(`高 = r`, rx - 45, ry + rectH/2 + 5);
    }

    // Explanation Banner
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('圓面積公式極限推導: S = 底邊 × 高 = (π × r) × r = π × r²', 80, 310);
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#15803d';
    ctx.fillText('✔ 轉化思想：等分數 n 越大，邊界越趨向平直，剪拼圖形無限逼近精確長方形！', 80, 335);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">等分數:</span><span class="readout-val">${n} 份</span></div>
      <div class="readout-item"><span class="readout-lbl">拼成長方形底:</span><span class="readout-val highlight">π r</span></div>
      <div class="readout-item"><span class="readout-lbl">長方形高:</span><span class="readout-val">r</span></div>
      <div class="readout-item"><span class="readout-lbl">面積模型:</span><span class="readout-val success">S = π r²</span></div>
    `;

    currentRecordGetter = () => [
      `${n} 等分`, `${(p*100).toFixed(0)}%`, 'π r', 'r', 'π r²', '微積分極限'
    ];
  }

  slS.oninput = update; slU.oninput = update;
  resetBtn.onclick = () => { slS.value = 2; slU.value = 0; update(); };
  update();
};



// ----------------------------------------------------------------------------
// Week 23: 披薩店的幾何密碼 (Pizza Area Scaling)
// ----------------------------------------------------------------------------
window.initExp_W23 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>大披薩直徑 D1 (吋)</span><span id="vD1_23" class="control-val">12</span></div>
      <input type="range" id="slD1_23" class="control-slider" min="10" max="16" step="1" value="12">
    </div>
    <div class="control-group">
      <div class="control-label"><span>小披薩直徑 D2 (吋)</span><span id="vD2_23" class="control-val">9</span></div>
      <input type="range" id="slD2_23" class="control-slider" min="6" max="10" step="1" value="9">
    </div>
  `;

  const s1 = document.getElementById('slD1_23'), s2 = document.getElementById('slD2_23');

  function update() {
    const d1 = parseInt(s1.value), d2 = parseInt(s2.value);
    document.getElementById('vD1_23').textContent = d1;
    document.getElementById('vD2_23').textContent = d2;

    const r1 = d1 / 2, r2 = d2 / 2;
    const a1 = Math.PI * r1 * r1;
    const a2 = Math.PI * r2 * r2;
    const a2_double = a2 * 2;
    const diff = (a2_double - a1).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`披薩面積二次方律對比：1 個 ${d1} 吋大披薩 vs 2 個 ${d2} 吋小披薩:`, 40, 40);

    // Pizza 1
    const p1X = 180, p1Y = 170, p1R = r1 * 8;
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath(); ctx.arc(p1X, p1Y, p1R, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = '#b45309'; ctx.lineWidth = 4; ctx.stroke();

    // Pepperonis
    ctx.fillStyle = '#dc2626';
    for (let i = 0; i < 6; i++) {
      const pa = (i * 2 * Math.PI) / 6;
      ctx.beginPath(); ctx.arc(p1X + Math.cos(pa)*p1R*0.5, p1Y + Math.sin(pa)*p1R*0.5, 7, 0, Math.PI*2); ctx.fill();
    }
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(`1 個 ${d1} 吋大披薩`, p1X, p1Y + p1R + 25);
    ctx.fillText(`面積: ${a1.toFixed(1)} 平方吋`, p1X, p1Y + p1R + 42);

    // Pizza 2 (Double small)
    const p2R = r2 * 8;
    const p2X_a = 430, p2Y_a = 130;
    const p2X_b = 530, p2Y_b = 210;

    [ {x: p2X_a, y: p2Y_a}, {x: p2X_b, y: p2Y_b} ].forEach((pos, idx) => {
      ctx.fillStyle = '#f59e0b';
      ctx.beginPath(); ctx.arc(pos.x, pos.y, p2R, 0, Math.PI*2); ctx.fill();
      ctx.strokeStyle = '#b45309'; ctx.lineWidth = 3; ctx.stroke();
      ctx.fillStyle = '#dc2626';
      ctx.beginPath(); ctx.arc(pos.x, pos.y, 6, 0, Math.PI*2); ctx.fill();
    });

    ctx.fillStyle = '#0f172a';
    ctx.fillText(`2 個 ${d2} 吋小披薩`, 480, 295);
    ctx.fillText(`總面積: ${a2_double.toFixed(1)} 平方吋`, 480, 315);

    // Summary banner
    ctx.textAlign = 'left';
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 14px sans-serif';
    const isDoubleBetter = a2_double > a1;
    ctx.fillText(isDoubleBetter ? `✔ 兩小披薩總面積多出 ${diff} 平方吋 (多出 ${((diff/a1)*100).toFixed(1)}%)，若同價買 2 個小披薩更划算！` : `✔ 大披薩面積大於 2 個小披薩 (多出 ${Math.abs(diff)} 平方吋)，買 1 個大披薩更超值！`, 60, 350);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">大披薩:</span><span class="readout-val">${a1.toFixed(1)} inch²</span></div>
      <div class="readout-item"><span class="readout-lbl">兩小披薩:</span><span class="readout-val highlight">${a2_double.toFixed(1)} inch²</span></div>
      <div class="readout-item"><span class="readout-lbl">面積差額:</span><span class="readout-val">${Math.abs(diff)} inch²</span></div>
      <div class="readout-item"><span class="readout-lbl">最優決策:</span><span class="readout-val success">${isDoubleBetter?'買2個小披薩':'買1個大披薩'}</span></div>
    `;

    currentRecordGetter = () => [
      `對比 1個${d1}吋 vs 2個${d2}吋`, `${d1} 吋`, `${d2} 吋`, `${a1.toFixed(1)} inch²`, `${a2_double.toFixed(1)} inch²`, isDoubleBetter ? '2個小披薩更大' : '1個大披薩更大'
    ];
  }

  s1.oninput = update; s2.oninput = update;
  resetBtn.onclick = () => { s1.value = 12; s2.value = 9; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 24: 澳門友誼大橋區間測速 (Section Speed Camera)
// ----------------------------------------------------------------------------
window.initExp_W24 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>通過大橋耗時 t (分鐘)</span><span id="vTime24" class="control-val">3.5</span></div>
      <input type="range" id="slTime24" class="control-slider" min="2.0" max="6.0" step="0.1" value="3.5">
    </div>
  `;

  const slT = document.getElementById('slTime24');

  function update() {
    const tMin = parseFloat(slT.value);
    document.getElementById('vTime24').textContent = `${tMin.toFixed(1)} 分鐘`;

    const bridgeL = 4.4; // km
    const avgSpeed = (bridgeL / (tMin / 60)).toFixed(1); // km/h
    const speedLimit = 80; // km/h
    const isOver = parseFloat(avgSpeed) > speedLimit;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`澳門友誼大橋區間測速演算法執法模型 (全長 L = 4.4 km, 最高限速 80 km/h):`, 40, 40);

    // Sea & Bridge
    ctx.fillStyle = '#38bdf8';
    ctx.fillRect(40, 160, 620, 100);

    // Bridge piers & deck
    ctx.fillStyle = '#94a3b8';
    ctx.fillRect(40, 180, 620, 24);
    for (let p = 60; p < 640; p += 70) {
      ctx.fillStyle = '#64748b';
      ctx.fillRect(p, 204, 16, 56);
    }

    // Gantries
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(70, 140, 10, 40);
    ctx.fillRect(570, 140, 10, 40);
    ctx.font = 'bold 11px sans-serif';
    ctx.fillText('起點抓拍', 55, 130);
    ctx.fillText('終點抓拍', 555, 130);

    // Car on bridge
    ctx.fillStyle = isOver ? '#dc2626' : '#2563eb';
    ctx.fillRect(320, 165, 36, 16);

    // Formula Card
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(80, 280, 520, 75);
    ctx.strokeStyle = isOver ? '#ef4444' : '#10b981';
    ctx.strokeRect(80, 280, 520, 75);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`區間平均時速 v = 4.4 km ÷ (${tMin} ÷ 60) h = ${avgSpeed} km/h`, 100, 310);

    ctx.font = 'bold 14px sans-serif';
    ctx.fillStyle = isOver ? '#dc2626' : '#15803d';
    ctx.fillText(isOver ? `⚠️ 區間超速違法！超出限速 ${(avgSpeed - speedLimit).toFixed(1)} km/h，處罰款 2,000 MOP` : '✔ 速度合規安全通行 (平均時速低於 80 km/h)', 100, 338);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">大橋全長:</span><span class="readout-val">4.4 km</span></div>
      <div class="readout-item"><span class="readout-lbl">耗時:</span><span class="readout-val">${tMin.toFixed(1)} 分鐘</span></div>
      <div class="readout-item"><span class="readout-lbl">區間平均速度:</span><span class="readout-val highlight">${avgSpeed} km/h</span></div>
      <div class="readout-item"><span class="readout-lbl">測速結果:</span><span class="readout-val ${isOver?'danger':'success'}">${isOver?'超速違章':'正常'}</span></div>
    `;

    currentRecordGetter = () => [
      `過橋 ${tMin}分鐘`, '4.4 km', `${tMin.toFixed(1)} 分鐘`, `${avgSpeed} km/h`, '80 km/h', isOver ? '超速處罰' : '正常'
    ];
  }

  slT.oninput = update;
  resetBtn.onclick = () => { slT.value = 3.5; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 25: 港珠澳大橋穿梭巴士相遇與追及 (Shuttle Buses Meeting & Overtaking)
// ----------------------------------------------------------------------------
window.initExp_W25 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>巴士 A 速度 (km/h)</span><span id="vBusA" class="control-val">80</span></div>
      <input type="range" id="slBusA" class="control-slider" min="50" max="100" step="5" value="80">
    </div>
    <div class="control-group">
      <div class="control-label"><span>巴士 B 速度 (km/h)</span><span id="vBusB" class="control-val">60</span></div>
      <input type="range" id="slBusB" class="control-slider" min="40" max="90" step="5" value="60">
    </div>
  `;

  const sA = document.getElementById('slBusA'), sB = document.getElementById('slBusB');

  function update() {
    const vA = parseInt(sA.value), vB = parseInt(sB.value);
    document.getElementById('vBusA').textContent = vA;
    document.getElementById('vBusB').textContent = vB;

    const totalDist = 55; // km
    const meetTimeMin = ((totalDist / (vA + vB)) * 60).toFixed(1);
    const meetDistFromA = (vA * (totalDist / (vA + vB))).toFixed(1);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`港珠澳大橋 55km 穿梭金巴相遇時空動態模型:`, 40, 45);

    // Bridge Line
    const bx1 = 80, bx2 = 600, by = 170;
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 14;
    ctx.beginPath(); ctx.moveTo(bx1, by); ctx.lineTo(bx2, by); ctx.stroke();

    // Terminals
    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 12px sans-serif';
    ctx.fillText('珠海口岸 (0km)', bx1 - 25, by - 20);
    ctx.fillText('澳門/香港口岸 (55km)', bx2 - 60, by - 20);

    // Meeting point
    const meetX = bx1 + (meetDistFromA / totalDist) * (bx2 - bx1);
    ctx.strokeStyle = '#ef4444';
    ctx.setLineDash([4, 4]);
    ctx.beginPath(); ctx.moveTo(meetX, by - 40); ctx.lineTo(meetX, by + 40); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#ef4444';
    ctx.fillText(`相遇點 (${meetDistFromA}km)`, meetX - 35, by + 55);

    // Bus A & B
    ctx.fillStyle = '#eab308';
    ctx.fillRect(bx1 + 30, by - 20, 34, 16);
    ctx.fillStyle = '#0284c7';
    ctx.fillRect(bx2 - 60, by + 4, 34, 16);

    // Formula summary
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`相遇時間 t = 55 km ÷ (${vA} + ${vB}) km/h = ${(totalDist/(vA+vB)).toFixed(2)} 小時 (${meetTimeMin} 分鐘)`, 80, 290);
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#059669';
    ctx.fillText(`距離珠海口岸: ${meetDistFromA} 公里處相遇。`, 80, 318);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總長度:</span><span class="readout-val">55 km</span></div>
      <div class="readout-item"><span class="readout-lbl">相對速度:</span><span class="readout-val highlight">${vA + vB} km/h</span></div>
      <div class="readout-item"><span class="readout-lbl">相遇時間:</span><span class="readout-val success">${meetTimeMin} 分鐘</span></div>
      <div class="readout-item"><span class="readout-lbl">相遇地點:</span><span class="readout-val">距起點 ${meetDistFromA} km</span></div>
    `;

    currentRecordGetter = () => [
      `金巴相遇組`, `${vA} km/h`, `${vB} km/h`, `${vA + vB} km/h`, `${meetTimeMin} 分鐘`, `${meetDistFromA} km`
    ];
  }

  sA.oninput = update; sB.oninput = update;
  resetBtn.onclick = () => { sA.value = 80; sB.value = 60; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 26: 解讀運動圖表：位移-時間 (Kinematics s-t Graph)
// ----------------------------------------------------------------------------
window.initExp_W26 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>當前運動時間 t (秒)</span><span id="vTime26" class="control-val">15</span></div>
      <input type="range" id="slTime26" class="control-slider" min="0" max="30" value="15">
    </div>
  `;

  const slT = document.getElementById('slTime26');

  function update() {
    const t = parseInt(slT.value);
    document.getElementById('vTime26').textContent = `${t} 秒`;

    // 0-10s: forward to 800m (v = 80)
    // 10-20s: rest (s = 800)
    // 20-30s: return back to 0m (v = -80)
    let s = 0, state = '', speed = 0;
    if (t <= 10) {
      s = t * 80;
      speed = 80;
      state = '勻速前進 (斜率為正)';
    } else if (t <= 20) {
      s = 800;
      speed = 0;
      state = '停留休息 (水平線斜率為0)';
    } else {
      s = 800 - (t - 20) * 80;
      speed = -80;
      state = '反向折返 (斜率為負)';
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('位移-時間 (s-t) 圖物理故事與斜率速度解讀:', 40, 40);

    // Graph axes
    const ox = 80, oy = 260, gw = 500, gh = 180;
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox + gw, oy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox, oy - gh); ctx.stroke();

    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#475569';
    ctx.fillText('時間 t (s)', ox + gw - 30, oy + 25);
    ctx.fillText('位移 s (m)', ox - 40, oy - gh + 10);

    // Full curve
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(ox, oy);
    ctx.lineTo(ox + (10/30)*gw, oy - (800/1000)*gh);
    ctx.lineTo(ox + (20/30)*gw, oy - (800/1000)*gh);
    ctx.lineTo(ox + gw, oy);
    ctx.stroke();

    // Dot at current t
    const curX = ox + (t / 30) * gw;
    const curY = oy - (s / 1000) * gh;
    ctx.fillStyle = '#ef4444';
    ctx.beginPath(); ctx.arc(curX, curY, 6, 0, Math.PI*2); ctx.fill();

    // Summary banner
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`當前時刻 t = ${t}s ➔ 距起點位移 s = ${s} 米 | 瞬時速度 v = ${speed} m/s`, 80, 310);
    ctx.font = '13px sans-serif';
    ctx.fillStyle = '#059669';
    ctx.fillText(`物理狀態：${state}`, 80, 335);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">時間:</span><span class="readout-val">${t} 秒</span></div>
      <div class="readout-item"><span class="readout-lbl">當前位移:</span><span class="readout-val highlight">${s} 米</span></div>
      <div class="readout-item"><span class="readout-lbl">瞬時速度:</span><span class="readout-val">${speed} m/s</span></div>
      <div class="readout-item"><span class="readout-lbl">圖表特徵:</span><span class="readout-val success">${speed===0?'水平停留':'傾斜運動'}</span></div>
    `;

    currentRecordGetter = () => [
      `時刻 ${t}s`, `${t} 秒`, `${s} 米`, `${speed} m/s`, state
    ];
  }

  slT.oninput = update;
  resetBtn.onclick = () => { slT.value = 15; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 27: 天平平衡原理與代數等量思維 (Algebraic Balance Scale)
// ----------------------------------------------------------------------------
window.initExp_W27 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>未知數 x 的設定值</span><span id="vX27" class="control-val">4</span></div>
      <input type="range" id="slX27" class="control-slider" min="1" max="10" value="4">
    </div>
    <div class="control-group">
      <div class="control-label"><span>左盤常數砝碼 b</span><span id="vB27" class="control-val">6</span></div>
      <input type="range" id="slB27" class="control-slider" min="0" max="20" value="6">
    </div>
  `;

  const sx = document.getElementById('slX27'), sb = document.getElementById('slB27');

  function update() {
    const x = parseInt(sx.value);
    const b = parseInt(sb.value);
    document.getElementById('vX27').textContent = x;
    document.getElementById('vB27').textContent = b;

    // Equation: 2x + b = RightSide
    const leftWeight = 2 * x + b;
    const rightWeight = 14; // fixed target
    const diff = leftWeight - rightWeight;
    const tilt = Math.max(-0.25, Math.min(0.25, diff * 0.03));
    const isBalanced = (diff === 0);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`代數等量天平模型：2x + ${b} = 14 (兩端平衡求解 x):`, 40, 40);

    // Balance Fulcrum
    const fx = 350, fy = 240;
    ctx.fillStyle = '#475569';
    ctx.beginPath();
    ctx.moveTo(fx, fy - 20); ctx.lineTo(fx - 25, fy + 40); ctx.lineTo(fx + 25, fy + 40);
    ctx.closePath(); ctx.fill();

    // Beam
    ctx.save();
    ctx.translate(fx, fy - 20);
    ctx.rotate(tilt);

    ctx.fillStyle = '#1e293b';
    ctx.fillRect(-180, -6, 360, 12);

    // Left Pan
    ctx.strokeStyle = '#94a3b8';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-160, 0); ctx.lineTo(-160, 60); ctx.stroke();
    ctx.fillStyle = '#cbd5e1';
    ctx.fillRect(-195, 60, 70, 10);
    // Left Weights
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(-190, 36, 26, 24); // x bag 1
    ctx.fillRect(-160, 36, 26, 24); // x bag 2
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 12px sans-serif';
    ctx.fillText('x', -180, 52); ctx.fillText('x', -150, 52);

    // Right Pan
    ctx.beginPath(); ctx.moveTo(160, 0); ctx.lineTo(160, 60); ctx.stroke();
    ctx.fillStyle = '#cbd5e1';
    ctx.fillRect(125, 60, 70, 10);
    // Right Weights
    ctx.fillStyle = '#10b981';
    ctx.fillRect(140, 36, 40, 24);
    ctx.fillStyle = '#ffffff';
    ctx.fillText('14', 152, 52);
    ctx.restore();

    // Equation solution text
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`左盤總質量: 2x + ${b} = ${leftWeight} | 右盤砝碼: 14`, 80, 310);
    ctx.font = 'bold 14px sans-serif';
    ctx.fillStyle = isBalanced ? '#15803d' : '#dc2626';
    ctx.fillText(isBalanced ? `✔ 天平完美平衡！求解得未知數 x = (14 - ${b}) ÷ 2 = ${x}` : `✘ 天平${diff>0?'向左傾斜(過重)':'向右傾斜(過輕)'}，調節 x 至 ${(14-b)/2} 即可平衡。`, 80, 335);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">左盤代數式:</span><span class="readout-val">2x + ${b}</span></div>
      <div class="readout-item"><span class="readout-lbl">右盤重量:</span><span class="readout-val">14</span></div>
      <div class="readout-item"><span class="readout-lbl">天平狀態:</span><span class="readout-val ${isBalanced?'success':'danger'}">${isBalanced?'平衡':'失衡'}</span></div>
      <div class="readout-item"><span class="readout-lbl">未知數解:</span><span class="readout-val highlight">x = ${(14-b)/2}</span></div>
    `;

    currentRecordGetter = () => [
      `方程 2x+${b}=14`, `x = ${x}`, `${b}`, `${leftWeight}`, '14', isBalanced ? '平衡' : '傾斜', `x = ${(14-b)/2}`
    ];
  }

  sx.oninput = update; sb.oninput = update;
  resetBtn.onclick = () => { sx.value = 4; sb.value = 6; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 28: 破解神奇讀心術 (Mind Reading 9-Multiple Grid)
// ----------------------------------------------------------------------------
window.initExp_W28 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>任意選擇兩位數 N</span><span id="vNum28" class="control-val">42</span></div>
      <input type="range" id="slNum28" class="control-slider" min="10" max="99" value="42">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="btnReveal28">🔮 啟動代數讀心水晶球</button>
    </div>
  `;

  let N = 42;
  const slN = document.getElementById('slNum28');

  function update() {
    N = parseInt(slN.value);
    document.getElementById('vNum28').textContent = N;

    const ten = Math.floor(N / 10);
    const unit = N % 10;
    const digitSum = ten + unit;
    const result = N - digitSum; // always 9 * ten

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('破解神奇讀心術：任意兩位數減去各位和恆等於 9 的倍數:', 40, 40);

    // Number breakdown
    ctx.fillStyle = '#3b82f6';
    ctx.font = '14px sans-serif';
    ctx.fillText(`你選擇的兩位數 N = ${N} (十位: ${ten}, 個位: ${unit})`, 60, 75);
    ctx.fillText(`各位數字之和: ${ten} + ${unit} = ${digitSum}`, 60, 105);
    ctx.fillStyle = '#15803d';
    ctx.font = 'bold 16px sans-serif';
    ctx.fillText(`差值運算: ${N} - ${digitSum} = ${result} (恆為 9 的倍數: 9 × ${ten})`, 60, 140);

    // Visual Board
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(60, 170, 580, 150);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(60, 170, 580, 150);

    ctx.fillStyle = '#6b21a8';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('🔮 水晶球解密代數定理證明：', 80, 205);

    ctx.fillStyle = '#0f172a';
    ctx.font = '14px sans-serif';
    ctx.fillText('設任意兩位數為 10a + b，則其減去各位和為：', 80, 235);
    ctx.font = 'bold 15px sans-serif';
    ctx.fillStyle = '#2563eb';
    ctx.fillText('(10a + b) - (a + b) = 10a + b - a - b = 9a', 80, 265);

    ctx.fillStyle = '#15803d';
    ctx.font = '13px sans-serif';
    ctx.fillText('結論：結果只與十位 a 有關，且永遠是 9 的倍數！魔術師在 9, 18, 27... 印上相同圖案即可讀心。', 80, 295);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">所選數字:</span><span class="readout-val">${N}</span></div>
      <div class="readout-item"><span class="readout-lbl">數字和:</span><span class="readout-val">${digitSum}</span></div>
      <div class="readout-item"><span class="readout-lbl">相減結果:</span><span class="readout-val highlight">${result}</span></div>
      <div class="readout-item"><span class="readout-lbl">數學本質:</span><span class="readout-val success">9 × ${ten}</span></div>
    `;

    currentRecordGetter = () => [
      `選數 ${N}`, `${N}`, `${digitSum}`, `${result}`, `9 × ${ten}`, '100% 命中'
    ];
  }

  slN.oninput = update;
  resetBtn.onclick = () => { slN.value = 42; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 29: 澳門智慧停車場調度 (Smart Parking & Chicken-Rabbit)
// ----------------------------------------------------------------------------
window.initExp_W29 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>車輛總數 H (輛)</span><span id="vVeh" class="control-val">20</span></div>
      <input type="range" id="slVeh" class="control-slider" min="10" max="40" step="2" value="20">
    </div>
    <div class="control-group">
      <div class="control-label"><span>其中汽車數量 (4輪)</span><span id="vCars" class="control-val">12</span></div>
      <input type="range" id="slCars" class="control-slider" min="0" max="20" value="12">
    </div>
  `;

  const sV = document.getElementById('slVeh'), sC = document.getElementById('slCars');

  function update() {
    const totalVeh = parseInt(sV.value);
    sC.max = totalVeh;
    const cars = Math.min(totalVeh, parseInt(sC.value));
    const motos = totalVeh - cars;
    const totalWheels = cars * 4 + motos * 2;

    document.getElementById('vVeh').textContent = totalVeh;
    document.getElementById('vCars').textContent = cars;

    // Hypothetic assumption: if all were motorcycles (2 wheels)
    const hypoWheels = totalVeh * 2;
    const extraWheels = totalWheels - hypoWheels;
    const solvedCars = extraWheels / 2;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`智慧停車場車輛識別（雞兔同籠模型）：總車數 ${totalVeh} 輛，輪胎傳感器測得 ${totalWheels} 輪:`, 40, 40);

    // Draw Parking grid
    const startX = 60, startY = 75;
    for (let i = 0; i < totalVeh; i++) {
      const gx = startX + (i % 10) * 58;
      const gy = startY + Math.floor(i / 10) * 50;
      const isCar = (i < cars);

      ctx.fillStyle = isCar ? '#3b82f6' : '#f59e0b';
      ctx.fillRect(gx, gy, 48, 30);
      ctx.strokeStyle = '#0f172a';
      ctx.strokeRect(gx, gy, 48, 30);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(isCar ? '🚗 4輪' : '🛵 2輪', gx + 24, gy + 20);
    }

    // Mathematical Deduction Box
    ctx.textAlign = 'left';
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(40, 210, 620, 130);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(40, 210, 620, 130);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('★ 抬腳假設法推導演算法：', 60, 240);

    ctx.font = '14px sans-serif';
    ctx.fillStyle = '#334155';
    ctx.fillText(`1. 假設 ${totalVeh} 輛全為 2 輪電單車，輪胎總數應為: ${totalVeh} × 2 = ${hypoWheels} 輪`, 60, 268);
    ctx.fillText(`2. 比實際 ${totalWheels} 輪少出的差額為: ${totalWheels} - ${hypoWheels} = ${extraWheels} 輪 (屬於汽車的後雙輪)`, 60, 294);

    ctx.fillStyle = '#15803d';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`3. 汽車數量 = ${extraWheels} ÷ 2 = ${solvedCars} 輛；電單車數量 = ${totalVeh} - ${solvedCars} = ${motos} 輛`, 60, 322);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總車數:</span><span class="readout-val">${totalVeh} 輛</span></div>
      <div class="readout-item"><span class="readout-lbl">輪胎總數:</span><span class="readout-val highlight">${totalWheels} 輪</span></div>
      <div class="readout-item"><span class="readout-lbl">汽車數量:</span><span class="readout-val success">${cars} 輛</span></div>
      <div class="readout-item"><span class="readout-lbl">電單車數量:</span><span class="readout-val">${motos} 輛</span></div>
    `;

    currentRecordGetter = () => [
      `車輛 ${totalVeh}輛`, `${totalVeh} 輛`, `${totalWheels} 輪`, `${hypoWheels} 輪`, `${cars} 輛汽車`, `${motos} 輛電單車`
    ];
  }

  sV.oninput = update; sC.oninput = update;
  resetBtn.onclick = () => { sV.value = 20; sC.value = 12; update(); };
  update();
};

// ----------------------------------------------------------------------------
// Week 30: 「平均薪資 5 萬」的真相：中位數與離群值 (Salary Distribution)
// ----------------------------------------------------------------------------
window.initExp_W30 = function(controls, canvas, ctx, readout, resetBtn) {
  controls.innerHTML = `
    <div class="control-group">
      <div class="control-label"><span>高管離群值月薪 (萬元)</span><span id="vCeo" class="control-val">100</span></div>
      <input type="range" id="slCeo" class="control-slider" min="20" max="300" step="10" value="100">
    </div>
    <div class="control-btn-group">
      <button class="btn-toggle active" id="bWithCeo">包含 1 位億萬高管</button>
      <button class="btn-toggle" id="bNoCeo">剔除極端離群值</button>
    </div>
  `;

  let ceoSalary = 1000000, hasCeo = true;
  const slC = document.getElementById('slCeo');
  const bWith = document.getElementById('bWithCeo'), bNo = document.getElementById('bNoCeo');

  bWith.onclick = () => { hasCeo = true; bWith.classList.add('active'); bNo.classList.remove('active'); update(); };
  bNo.onclick = () => { hasCeo = false; bNo.classList.add('active'); bWith.classList.remove('active'); update(); };

  function update() {
    ceoSalary = parseInt(slC.value) * 10000;
    document.getElementById('vCeo').textContent = slC.value;

    // Normal 19 employees: avg ~15,000
    const normalSalaries = [12000, 13000, 13500, 14000, 14500, 15000, 15000, 15500, 16000, 16000, 16500, 17000, 17500, 18000, 18500, 19000, 20000, 22000, 25000];
    let allSalaries = [...normalSalaries];
    if (hasCeo) allSalaries.push(ceoSalary);
    allSalaries.sort((a, b) => a - b);

    const sum = allSalaries.reduce((acc, v) => acc + v, 0);
    const mean = (sum / allSalaries.length).toFixed(0);
    const midIdx = Math.floor(allSalaries.length / 2);
    const median = allSalaries.length % 2 === 1 ? allSalaries[midIdx] : ((allSalaries[midIdx - 1] + allSalaries[midIdx]) / 2);
    const belowMean = allSalaries.filter(s => s < parseFloat(mean)).length;
    const belowMeanRate = ((belowMean / allSalaries.length) * 100).toFixed(0);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();

    ctx.fillStyle = '#0f172a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText('MAIL 數據批判：極端離群值對平均數的拉抬與中位數穩健性對比:', 40, 40);

    // Dot Plot on axis
    const ox = 70, oy = 210, gw = 540;
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox + gw, oy); ctx.stroke();

    const maxPlot = hasCeo ? 300000 : 30000;
    allSalaries.forEach(s => {
      const px = ox + Math.min(1.0, s / maxPlot) * gw;
      ctx.fillStyle = (s === ceoSalary && hasCeo) ? '#dc2626' : '#3b82f6';
      ctx.beginPath(); ctx.arc(px, oy - 15, (s===ceoSalary&&hasCeo)?9:5, 0, Math.PI*2); ctx.fill();
    });

    // Vertical Mean line
    const meanX = ox + Math.min(1.0, mean / maxPlot) * gw;
    ctx.strokeStyle = '#dc2626';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(meanX, oy - 90); ctx.lineTo(meanX, oy + 25); ctx.stroke();
    ctx.fillStyle = '#dc2626';
    ctx.font = 'bold 12px sans-serif';
    ctx.fillText(`平均數: $${parseInt(mean).toLocaleString()}`, meanX - 40, oy - 98);

    // Vertical Median line
    const medianX = ox + Math.min(1.0, median / maxPlot) * gw;
    ctx.strokeStyle = '#16a34a';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(medianX, oy - 60); ctx.lineTo(medianX, oy + 25); ctx.stroke();
    ctx.fillStyle = '#16a34a';
    ctx.fillText(`中位數: $${parseInt(median).toLocaleString()}`, medianX - 40, oy - 68);

    // Summary Banner
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(40, 250, 620, 95);
    ctx.strokeStyle = '#cbd5e1';
    ctx.strokeRect(40, 250, 620, 95);

    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(`平均數 = $${parseInt(mean).toLocaleString()} 元 | 中位數 = $${parseInt(median).toLocaleString()} 元 | 差額 = $${(mean - median).toLocaleString()} 元`, 60, 280);

    ctx.font = '13px sans-serif';
    ctx.fillStyle = hasCeo ? '#dc2626' : '#15803d';
    ctx.fillText(hasCeo ? `⚠️ 審查震撼真相：全體員工中有高達 ${belowMeanRate}% (${belowMean}/${allSalaries.length}人) 薪資低於所謂的「平均工資」！` : '✔ 剔除離群值後，平均數與中位數高度吻合，能客觀反映普遍大眾生活水準。', 60, 310);
    ctx.restore();

    readout.innerHTML = `
      <div class="readout-item"><span class="readout-lbl">總人數:</span><span class="readout-val">${allSalaries.length} 人</span></div>
      <div class="readout-item"><span class="readout-lbl">平均薪資:</span><span class="readout-val danger">$${parseInt(mean).toLocaleString()}</span></div>
      <div class="readout-item"><span class="readout-lbl">中位數薪資:</span><span class="readout-val success">$${parseInt(median).toLocaleString()}</span></div>
      <div class="readout-item"><span class="readout-lbl">低於平均佔比:</span><span class="readout-val highlight">${belowMeanRate}%</span></div>
    `;

    currentRecordGetter = () => [
      hasCeo ? '含極端高薪' : '剔除離群值', `${allSalaries.length} 人`, `$${parseInt(mean).toLocaleString()}`, `$${parseInt(median).toLocaleString()}`, `${belowMeanRate}%`, hasCeo ? '嚴重失真' : '客觀'
    ];
  }

  slC.oninput = update;
  resetBtn.onclick = () => { slC.value = 100; bWith.click(); };
  update();
};


